// Текст закона для сайта (подключается при открытии раздела)
(window.LAW_DATA = window.LAW_DATA || {})["upk"] = {"items":[{"h":"Часть 1. Общие положения"},{"h":"Глава 1. Уголовно-процессуальное законодательство и принципы"},{"n":"Статья 1","title":"Законы, определяющие порядок уголовного судопроизводства","sub":[{"n":"1","text":"Порядок уголовного судопроизводства на территории Российской Федерации устанавливается настоящим Кодексом, основанным на Конституции Российской Федерации."},{"n":"2","text":"Порядок уголовного судопроизводства, установленный настоящим Кодексом, является обязательным для судов, органов прокуратуры, органов предварительного следствия и органов дознания, а также иных участников уголовного судопроизводства."},{"n":"3","text":"Понятия «уголовное судопроизводство» и «уголовный процесс» в настоящем Кодексе равнозначны."}]},{"n":"Статья 2","title":"Действие уголовно-процессуального закона во времени, пространстве и по кругу лиц","sub":[{"n":"1","text":"При производстве по уголовному делу применяется уголовно-процессуальный закон, действующий во время совершения соответствующего процессуального действия или принятия процессуального решения."},{"n":"2","text":"Действие уголовно-процессуального закона распространяется на всю территорию Российской Федерации, а также на граждан Российской Федерации и иностранных граждан в случаях, предусмотренных международными договорами Российской Федерации и настоящим Кодексом."}]},{"n":"Статья 3","title":"Принципы уголовного судопроизводства","sub":[{"n":"1","text":"Назначением уголовного судопроизводства является защита прав и законных интересов лиц и организаций, потерпевших от преступлений, а также защита личности от незаконного и необоснованного обвинения, осуждения, ограничения ее прав и свобод."},{"n":"2","text":"Уголовное судопроизводство осуществляется на основе принципов законности, уважения чести и достоинства личности, неприкосновенности личности, презумпции невиновности, состязательности сторон и обеспечения подозреваемому (обвиняемому) права на защиту."}]},{"n":"Статья 4","title":"Основные понятия, используемые в настоящем Кодексе","sub":[{"n":"1","text":"Прокурор — Генеральный прокурор Российской Федерации и подчиненные ему прокуроры, их заместители и иные должностные лица прокуратуры, участвующие в уголовном судопроизводстве."},{"n":"2","text":"Следователь — должностное лицо, уполномоченное осуществлять предварительное следствие."},{"n":"3","text":"Дознаватель — должностное лицо органа дознания, уполномоченное осуществлять предварительное расследование в форме дознания."},{"n":"4","text":"Подозреваемый — лицо, в отношении которого возбуждено уголовное дело либо которое задержано по подозрению в совершении преступления."},{"n":"5","text":"Обвиняемый / Подсудимый — лицо, в отношении которого вынесено постановление о привлечении в качестве обвиняемого (на стадии судебного разбирательства — подсудимый)."}]},{"n":"Статья 5","title":"Презумпция невиновности","sub":[{"n":"1","text":"Обвиняемый считается невиновным, пока его виновность в совершении преступления не будет доказана в предусмотренном настоящим Кодексом порядке и установлена вступившим в законную силу приговором суда."},{"n":"2","text":"Подозреваемый или обвиняемый не обязан доказывать свою невиновность. Бремя доказывания обвинения и опровержения доводов, приводимых в защиту подозреваемого или обвиняемого, лежит на стороне обвинения."},{"n":"3","text":"Все сомнения в виновности обвиняемого, которые не могут быть устранены в порядке, установленном настоящим Кодексом, толкуются в пользу обвиняемого."},{"n":"4","text":"Обвинительный приговор не может быть основан на предположениях."},{"n":"5","text":"Неустранимые сомнения в виновности лица толкуются в пользу обвиняемого также при применении мер процессуального принуждения, при производстве следственных действий и при разрешении вопроса о достаточности доказательств."}]},{"n":"Статья 6","title":"Состязательность сторон","sub":[{"n":"1","text":"Уголовное судопроизводство осуществляется на основе состязательности сторон."},{"n":"2","text":"Функции обвинения, защиты и разрешения уголовного дела отделены друг от друга и не могут быть возложены на один и тот же орган или одно и то же должностное лицо."}]},{"n":"Статья 7","title":"Обеспечение подозреваемому и обвиняемому права на защиту","sub":[{"n":"1","text":"Подозреваемому и обвиняемому обеспечивается право на защиту, которое они могут осуществлять лично либо с помощью защитника и (или) законного представителя."},{"n":"2","text":"Суд, прокурор, следователь и дознаватель разъясняют подозреваемому и обвиняемому их права и обеспечивают им возможность защищаться всеми не запрещенными настоящим Кодексом способами и средствами."}]},{"n":"Статья 8","title":"Свобода оценки доказательств","sub":[{"n":"1","text":"Судья, присяжные заседатели, а также прокурор, следователь, дознаватель оценивают доказательства по своему внутреннему убеждению, основанному на совокупности имеющихся в уголовном деле доказательств, руководствуясь при этом законом и совестью."},{"n":"2","text":"Никакие доказательства не имеют заранее установленной силы."}]},{"n":"Статья 9","title":"Язык уголовного судопроизводства","sub":[{"n":"1","text":"Уголовное судопроизводство ведется на русском языке, а также на государственных языках входящих в Российскую Федерацию республик."},{"n":"2","text":"Участникам уголовного судопроизводства, не владеющим или недостаточно владеющим языком, на котором ведется производство по уголовному делу, обеспечивается право делать заявления, давать объяснения и показания, заявлять ходатайства, приносить жалобы, знакомиться с материалами уголовного дела, выступать в суде на родном языке или другом языке, которым они владеют, а также бесплатно пользоваться помощью переводчика в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 10","title":"Право на обжалование процессуальных действий и решений","sub":[{"n":"1","text":"Действия (бездействие) и решения органа дознания, дознавателя, следователя, руководителя следственного органа, прокурора и суда могут быть обжалованы в порядке, установленном настоящим Кодексом."}]},{"h":"Глава 2. Участники уголовного судопроизводства"},{"n":"Статья 11","title":"Суд","sub":[{"n":"1","text":"Суд является единственным органом, осуществляющим правосудие по уголовным делам."},{"n":"2","text":"Только суд уполномочен признать лицо виновным в совершении преступления и назначить ему наказание, а также санкционировать ограничение конституционных прав граждан (арест, обыск в жилище, ограничение тайны переписки и переговоров) в случаях и в порядке, предусмотренных настоящим Кодексом."}]},{"n":"Статья 12","title":"Сторона обвинения","sub":[{"n":"1","text":"К стороне обвинения относятся: прокурор, следователь, руководитель следственного органа, орган дознания, начальник органа дознания, начальник подразделения дознания, дознаватель, потерпевший, частный обвинитель, гражданский истец и их представители."}]},{"n":"Статья 13","title":"Следователь и руководитель следственного органа","sub":[{"n":"1","text":"Следователь является должностным лицом, уполномоченным в пределах компетенции, предусмотренной настоящим Кодексом, осуществлять предварительное следствие по уголовному делу."},{"n":"2","text":"Руководитель следственного органа осуществляет контроль за своевременностью и полнотой действий следователя, утверждает ключевые процессуальные решения и дает письменные указания по делу в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 14","title":"Орган дознания","sub":[{"n":"1","text":"К органам дознания относятся государственные органы и должностные лица, уполномоченные в соответствии с законом осуществлять дознание и производство неотложных следственных действий (органы внутренних дел / полиция, органы безопасности / ФСБ, органы ФССП, ФСИН и др.)."}]},{"n":"Статья 15","title":"Дознаватель","sub":[{"n":"1","text":"Дознаватель — должностное лицо органа дознания, правомочное осуществлять предварительное расследование в форме дознания по делам, не требующим обязательного производства предварительного следствия."}]},{"n":"Статья 16","title":"Начальник органа дознания и начальник подразделения дознания","sub":[{"n":"1","text":"Начальник органа дознания поручает производство дознания дознавателю, проверяет материалы дела, утверждает обвинительный акт или обвинительное постановление в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 17","title":"Потерпевший","sub":[{"n":"1","text":"Потерпевшим признается физическое лицо, которому преступлением причинен физический, имущественный или моральный вред, либо юридическое лицо в случае причинения вреда его имуществу и деловой репутации."}]},{"n":"Статья 18","title":"Сторона защиты","sub":[{"n":"1","text":"К стороне защиты относятся: подозреваемый, обвиняемый, подсудимый, защитник (адвокат), законные представители, гражданский ответчик и его представитель."},{"n":"2","text":"Защитник допускается к участию в уголовном деле с момента вынесения постановления о возбуждении уголовного дела либо с момента фактического задержания лица."},{"n":"3","text":"Защитник вправе: иметь с подозреваемым, обвиняемым свидания наедине без ограничения их количества и продолжительности; собирать и представлять доказательства; привлекать специалиста; присутствовать при предъявлении обвинения; участвовать в допросе и иных следственных действиях; знакомиться с протоколами; заявлять ходатайства и отводы; приносить жалобы."},{"n":"4","text":"Защитник обязан: не разглашать данные предварительного расследования, ставшие ему известными в связи с осуществлением защиты; не препятствовать производству по уголовному делу; являться по вызовам."},{"n":"5","text":"В случае неявки защитника и невозможности его замены следователь, дознаватель или суд обязаны обеспечить участие защитника по назначению в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 19","title":"Иные участники уголовного судопроизводства","sub":[{"n":"1","text":"В уголовном судопроизводстве также участвуют: свидетели, эксперты, специалисты, переводчики, понятые."}]},{"n":"Статья 20","title":"Свидетель","sub":[{"n":"1","text":"Свидетелем является лицо, которому могут быть известны какие-либо обстоятельства, имеющие значение для расследования и разрешения уголовного дела, и которое вызвано для дачи показаний в порядке, установленном настоящим Кодексом."},{"n":"2","text":"Не подлежат допросу в качестве свидетелей:"},{"n":"1)","text":"судья, присяжный заседатель — об обстоятельствах уголовного дела, которые стали им известны в связи с участием в производстве по данному уголовному делу;","lvl":1},{"n":"2)","text":"защитник, представитель — об обстоятельствах, которые стали им известны в связи с обращением к ним за юридической помощью.","lvl":1},{"n":"3","text":"Свидетель вправе: отказаться свидетельствовать против самого себя, своего супруга (супруги) и других близких родственников; давать показания на родном языке; заявлять ходатайства и отводы; приносить жалобы."},{"n":"4","text":"Свидетель не вправе: уклоняться от явки по вызовам; давать заведомо ложные показания либо отказываться от дачи показаний; разглашать данные предварительного расследования в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 21","title":"Эксперт","sub":[{"n":"1","text":"Эксперт — лицо, обладающее специальными знаниями и назначенное в порядке, установленном настоящим Кодексом, для производства судебной экспертизы и дачи заключения."},{"n":"2","text":"Эксперт вправе: знакомиться с материалами дела, относящимися к предмету экспертизы; заявлять ходатайства о предоставлении дополнительных материалов; участвовать с разрешения следователя в производстве следственных действий."},{"n":"3","text":"Эксперт не вправе: самостоятельно собирать материалы; вступать в личные контакты с участниками процесса; разглашать данные предварительного расследования."}]},{"n":"Статья 22","title":"Специалист","sub":[{"n":"1","text":"Специалист — лицо, обладающее специальными знаниями, привлекаемое к участию в процессуальных действиях для содействия в обнаружении, закреплении и изъятии предметов и документов, применении технических средств в порядке, установленном настоящим Кодексом."},{"n":"2","text":"Специалист вправе: отказаться от участия, если не обладает соответствующими специальными знаниями; задавать вопросы участникам следственного действия; знакомиться с протоколом и делать заявления."},{"n":"3","text":"Специалист не вправе уклоняться от явки по вызовам."}]},{"n":"Статья 23","title":"Переводчик","sub":[{"n":"1","text":"Переводчик — лицо, свободно владеющее языком, знание которого необходимо для перевода."},{"n":"2","text":"Переводчик вправе: задавать вопросы участникам для уточнения перевода; знакомиться с протоколом и делать замечания."},{"n":"3","text":"Переводчик не вправе: осуществлять заведомо неправильный перевод; разглашать данные предварительного расследования."}]},{"n":"Статья 24","title":"Понятой","sub":[{"n":"1","text":"Понятой — не заинтересованное в исходе уголовного дела лицо, привлекаемое для удостоверения факта производства следственного действия, а также содержания, хода и результатов следственного действия."},{"n":"2","text":"Понятыми не могут быть: несовершеннолетние; участники уголовного судопроизводства, их близкие родственники; работники органов исполнительной власти, наделенные полномочиями по осуществлению оперативно-розыскной деятельности."},{"n":"3","text":"Понятой вправе: участвовать в следственном действии; знакомиться с протоколом; приносить жалобы на действия следователя."}]},{"n":"Статья 25","title":"Гражданский истец","sub":[{"n":"1","text":"Гражданским истцом признается физическое или юридическое лицо, предъявившее требование о возмещении имущественного вреда, при наличии оснований полагать, что данный вред причинен ему непосредственно преступлением."},{"n":"2","text":"Гражданский истец вправе: поддерживать гражданский иск; представлять доказательства; давать объяснения; заявлять ходатайства и отводы."},{"n":"3","text":"Гражданский истец обязан: не разглашать данные предварительного расследования; являться по вызовам."}]},{"n":"Статья 26","title":"Гражданский ответчик","sub":[{"n":"1","text":"В качестве гражданского ответчика привлекается физическое или юридическое лицо, которое в силу закона несет ответственность за вред, причиненный преступлением."},{"n":"2","text":"Гражданский ответчик вправе: возражать против предъявленного гражданского иска; давать объяснения; собирать и представлять доказательства; заявлять ходатайства и отводы."}]},{"n":"Статья 27","title":"Законные представители несовершеннолетнего подозреваемого и обвиняемого","sub":[{"n":"1","text":"Законные представители несовершеннолетнего подозреваемого, обвиняемого допускаются к участию в уголовном деле с момента первого допроса несовершеннолетнего в качестве подозреваемого или обвиняемого."},{"n":"2","text":"Законный представитель вправе: знать, в чем подозревается или обвиняется несовершеннолетний; присутствовать при предъявлении обвинения; участвовать в допросе; заявлять ходатайства и отводы; приносить жалобы."}]},{"h":"Глава 3. Обстоятельства, исключающие участие в уголовном судопроизводстве"},{"n":"Статья 28","title":"Обстоятельства, исключающие участие в производстве по уголовному делу","sub":[{"n":"1","text":"Судья, прокурор, следователь, дознаватель не могут участвовать в производстве по уголовному делу, если они:"},{"n":"1)","text":"являются потерпевшим, гражданским истцом, гражданским ответчиком или свидетелем по данному уголовному делу;","lvl":1},{"n":"2)","text":"являлись участниками производства по данному делу в ином качестве;","lvl":1},{"n":"3)","text":"являются близкими родственниками или родственниками любого из участников производства по данному делу;","lvl":1},{"n":"4)","text":"лично, прямо или косвенно заинтересованы в исходе данного уголовного дела.","lvl":1},{"n":"2","text":"При наличии обстоятельств, указанных в части первой настоящей статьи, судья, прокурор, следователь, дознаватель обязаны заявить самоотвод."}]},{"n":"Статья 29","title":"Отвод судьи","sub":[{"n":"1","text":"Судья не может участвовать в рассмотрении уголовного дела:"},{"n":"1)","text":"если он принимал участие в производстве по данному делу в качестве прокурора, следователя, дознавателя, защитника, представителя, эксперта, специалиста, переводчика, свидетеля;","lvl":1},{"n":"2)","text":"если он рассматривал в отношении этого же лица уголовное дело в порядке судебного надзора, в качестве судьи апелляционной или кассационной инстанции.","lvl":1},{"n":"2","text":"Повторное участие судьи в рассмотрении уголовного дела недопустимо."}]},{"n":"Статья 30","title":"Отвод прокурора","sub":[{"n":"1","text":"Прокурор не может участвовать в производстве по уголовному делу, если он:"},{"n":"1)","text":"принимал участие в производстве по данному делу в качестве следователя, дознавателя, защитника, представителя, эксперта, специалиста, переводчика, свидетеля;","lvl":1},{"n":"2)","text":"является близким родственником или родственником потерпевшего, обвиняемого, защитника.","lvl":1},{"n":"2","text":"Решение об отводе прокурора принимается вышестоящим прокурором или судом в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 31","title":"Отвод следователя, руководителя следственного органа, дознавателя","sub":[{"n":"1","text":"Следователь, руководитель следственного органа, дознаватель не могут участвовать в производстве по делу при наличии обстоятельств, предусмотренных статьей 28 настоящего Кодекса."},{"n":"2","text":"Решение об отводе следователя принимается руководителем следственного органа; об отводе дознавателя — прокурором или начальником органа дознания."}]},{"n":"Статья 32","title":"Отвод эксперта, специалиста, переводчика","sub":[{"n":"1","text":"Эксперт, специалист, переводчик не могут принимать участие в производстве по делу:"},{"n":"1)","text":"при наличии обстоятельств, предусмотренных статьей 28 настоящего Кодекса;","lvl":1},{"n":"2)","text":"если они находились или находятся в служебной или иной зависимости от сторон;","lvl":1},{"n":"3)","text":"если обнаружится их некомпетентность.","lvl":1}]},{"h":"Часть 2. Досудебное производство"},{"h":"Глава 4. Доказательства и доказывание"},{"n":"Статья 33","title":"Обстоятельства, подлежащие доказыванию","sub":[{"n":"1","text":"событие преступления (время, место, способ и другие обстоятельства совершения преступления);"},{"n":"2","text":"виновность лица в совершении преступления, форма его вины и мотивы;"},{"n":"3","text":"обстоятельства, характеризующие личность обвиняемого;"},{"n":"4","text":"характер и размер вреда, причиненного преступлением;"},{"n":"5","text":"обстоятельства, исключающие преступность и наказуемость деяния;"},{"n":"6","text":"обстоятельства, смягчающие и отягчающие наказание."}],"text":"При производстве по уголовному делу подлежат доказыванию:"},{"n":"Статья 34","title":"Доказательства","sub":[{"n":"1","text":"Доказательствами по уголовному делу являются любые сведения, на основе которых суд, следователь, дознаватель в порядке, определенном настоящим Кодексом, устанавливают наличие или отсутствие обстоятельств, подлежащих доказыванию."},{"n":"2","text":"В качестве доказательств допускаются: показания подозреваемого, обвиняемого, потерпевшего, свидетеля, заключения экспертов, вещественные доказательства, протоколы следственных действий, иные документы."}]},{"n":"Статья 35","title":"Недопустимые доказательства","sub":[{"n":"1","text":"Доказательства, полученные с нарушением требований настоящего Кодекса, являются недопустимыми."},{"n":"2","text":"Недопустимые доказательства не имеют юридической силы и не могут быть положены в основу обвинения."}]},{"n":"Статья 36","title":"Правила оценки доказательств","sub":[{"n":"1","text":"Каждое доказательство подлежит оценке с точки зрения относимости, допустимости, достоверности, а все собранные доказательства в совокупности — достаточности для разрешения уголовного дела."}]},{"n":"Статья 37","title":"Показания подозреваемого и обвиняемого","sub":[{"n":"1","text":"Показания подозреваемого — сведения, сообщенные им на допросе, проведенном в ходе досудебного производства в соответствии с требованиями настоящего Кодекса."},{"n":"2","text":"Показания обвиняемого — сведения, сообщенные им на допросе, проведенном в ходе досудебного производства или в судебном заседании."},{"n":"3","text":"Признание обвиняемым своей вины в совершении преступления может быть положено в основу обвинения лишь при подтверждении его виновности совокупностью имеющихся по уголовному делу доказательств."}]},{"n":"Статья 38","title":"Показания потерпевшего и свидетеля","sub":[{"n":"1","text":"Показания потерпевшего — сведения, сообщенные им на допросе, проведенном в ходе досудебного производства или в судебном заседании."},{"n":"2","text":"Показания свидетеля — сведения, сообщенные им на допросе, проведенном в ходе досудебного производства или в судебном заседании."},{"n":"3","text":"Свидетель может быть допрошен о любых относящихся к уголовному делу обстоятельствах, в том числе о личности обвиняемого, потерпевшего и своих взаимоотношениях с ними."}]},{"n":"Статья 39","title":"Заключение и показания эксперта","sub":[{"n":"1","text":"Заключение эксперта — представленные в письменном виде содержание исследования и выводы по вопросам, поставленным перед экспертом лицом, ведущим производство по уголовному делу."},{"n":"2","text":"Показания эксперта — сведения, сообщенные им на допросе, проведенном после получения его заключения, в целях разъяснения или уточнения данного заключения."}]},{"n":"Статья 40","title":"Заключение и показания специалиста","sub":[{"n":"1","text":"Заключение специалиста — представленное в письменном виде суждение по вопросам, поставленным перед специалистом сторонами."},{"n":"2","text":"Показания специалиста — сведения, сообщенные им на допросе, об обстоятельствах, требующих специальных познаний."}]},{"n":"Статья 41","title":"Вещественные доказательства","sub":[{"n":"1","text":"Вещественными доказательствами признаются любые предметы:"},{"n":"1)","text":"которые служили орудиями преступления или сохранили на себе следы преступления;","lvl":1},{"n":"2)","text":"на которые были направлены преступные действия;","lvl":1},{"n":"3)","text":"иные предметы и документы, которые могут служить средствами для обнаружения преступления и установления обстоятельств уголовного дела.","lvl":1},{"n":"2","text":"Предметы, признанные вещественными доказательствами, осматриваются, признаются таковыми и приобщаются к уголовному делу в порядке, установленном настоящим Кодексом."},{"n":"3","text":"Вещественные доказательства хранятся при уголовном деле либо передаются на ответственное хранение в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 42","title":"Протоколы следственных действий и судебного заседания","sub":[{"n":"1","text":"Протоколы следственных действий и судебного заседания допускаются в качестве доказательств, если они соответствуют требованиям, установленным настоящим Кодексом."},{"n":"2","text":"Протокол должен содержать: место и дату производства следственного действия; время его начала и окончания; должность и фамилию лица, составившего протокол; фамилию, имя и отчество каждого лица, участвовавшего в следственном действии; содержание следственного действия; технические средства, примененные при производстве."}]},{"n":"Статья 43","title":"Иные документы","sub":[{"n":"1","text":"Иные документы допускаются в качестве доказательств, если изложенные в них сведения имеют значение для установления обстоятельств, подлежащих доказыванию."},{"n":"2","text":"Документы могут содержать сведения, зафиксированные как в письменном, так и в ином виде (фото-, кино-, аудио-, видеозаписи)."},{"n":"3","text":"Документы приобщаются к материалам уголовного дела и хранятся в течение всего срока его хранения в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 44","title":"Использование в доказывании результатов оперативно-розыскной деятельности","sub":[{"n":"1","text":"Результаты оперативно-розыскной деятельности могут быть использованы в доказывании по уголовным делам в соответствии с положениями настоящего Кодекса, регламентирующими собирание, проверку и оценку доказательств."}]},{"h":"Глава 5. Меры процессуального принуждения"},{"n":"Статья 45","title":"Основания и порядок задержания подозреваемого","sub":[{"n":"1","text":"Орган дознания, дознаватель, следователь вправе задержать лицо по подозрению в совершении преступления, за которое может быть назначено наказание в виде лишения свободы, при наличии одного из следующих оснований:"},{"n":"1)","text":"когда это лицо застигнуто при совершении преступления или непосредственно после его совершения;","lvl":1},{"n":"2)","text":"когда потерпевшие или очевидцы укажут на данное лицо как на совершившее преступление;","lvl":1},{"n":"3)","text":"когда на этом лице или его одежде, при нем или в его жилище будут обнаружены явные следы преступления.","lvl":1},{"n":"2","text":"Задержание подозреваемого производится на срок не более 48 часов с момента фактического задержания."},{"n":"3","text":"О произведенном задержании орган дознания, дознаватель или следователь обязан сообщить прокурору в письменном виде в течение 12 часов с момента задержания."},{"n":"4","text":"О задержании незамедлительно уведомляются: защитник; законные представители несовершеннолетнего; близкие родственники; администрация места работы или учебы; посольство или консульство иностранного государства, если задержанный является иностранным гражданином."},{"n":"5","text":"Задержанный имеет право: знать, в чем он подозревается; давать объяснения и показания; отказаться от дачи объяснений и показаний; пользоваться помощью защитника; знакомиться с протоколом задержания; заявлять ходатайства и приносить жалобы."},{"n":"6","text":"О каждом случае задержания составляется протокол в порядке, установленном статьей 46 настоящего Кодекса."}]},{"n":"Статья 46","title":"Протокол задержания подозреваемого","sub":[{"n":"1","text":"О задержании подозреваемого составляется протокол с указанием даты, времени, места, оснований, мотивов задержания, результатов личного обыска и других обстоятельств."},{"n":"2","text":"Протокол задержания подписывается лицом, его составившим, и подозреваемым."},{"n":"3","text":"Копия протокола вручается подозреваемому."},{"n":"4","text":"В протоколе указываются: дата, время и место составления; должность, фамилия и инициалы лица, составившего протокол; данные о подозреваемом; основания и мотивы задержания; время фактического задержания; сведения о разъяснении прав; сведения о защитнике; заявления и замечания подозреваемого."},{"n":"5","text":"При отказе подозреваемого подписать протокол в него вносится соответствующая запись, удостоверяемая подписью лица, составившего протокол, и защитника, если он участвует."},{"n":"6","text":"Копия протокола направляется прокурору в течение 12 часов с момента задержания."}]},{"n":"Статья 47","title":"Основания для избрания меры пресечения","sub":[{"n":"1","text":"Дознаватель, следователь, а также суд в пределах предоставленных им полномочий вправе избрать в отношении подозреваемого или обвиняемого одну из мер пресечения при наличии достаточных оснований полагать, что это лицо:"},{"n":"1)","text":"скроется от дознания, предварительного следствия или суда;","lvl":1},{"n":"2)","text":"может продолжать заниматься преступной деятельностью;","lvl":1},{"n":"3)","text":"может угрожать свидетелю, иным участникам уголовного судопроизводства, уничтожить доказательства либо иным путем воспрепятствовать производству по уголовному делу.","lvl":1},{"n":"2","text":"Мера пресечения может избираться также для обеспечения исполнения приговора."}]},{"n":"Статья 48","title":"Меры пресечения","sub":[{"n":"1","text":"подписка о невыезде и надлежащем поведении;"},{"n":"2","text":"личное поручительство;"},{"n":"3","text":"наблюдение командования воинской части;"},{"n":"4","text":"присмотр за несовершеннолетним подозреваемым или обвиняемым;"},{"n":"5","text":"запрет определенных действий;"},{"n":"6","text":"залог;"},{"n":"7","text":"домашний арест;"},{"n":"8","text":"заключение под стражу."}],"text":"Мерами пресечения являются:"},{"n":"Статья 49","title":"Обстоятельства, учитываемые при избрании меры пресечения","sub":[{"n":"1","text":"При решении вопроса о необходимости избрания меры пресечения и определения ее вида должны учитываться также тяжесть преступления, сведения о личности подозреваемого или обвиняемого, его возраст, состояние здоровья, семейное положение, род занятий и другие обстоятельства."}]},{"n":"Статья 50","title":"Избрание меры пресечения в отношении подозреваемого","sub":[{"n":"1","text":"В исключительных случаях при наличии оснований, предусмотренных статьей 47 настоящего Кодекса, и с учетом обстоятельств, указанных в статье 49 настоящего Кодекса, мера пресечения может быть избрана в отношении подозреваемого."},{"n":"2","text":"Обвинение должно быть предъявлено подозреваемому не позднее 10 суток с момента применения меры пресечения, а если подозреваемый был задержан, а затем заключен под стражу — в тот же срок с момента задержания. Если в этот срок обвинение не будет предъявлено, то мера пресечения немедленно отменяется."}]},{"n":"Статья 51","title":"Постановление и определение об избрании меры пресечения","sub":[{"n":"1","text":"Об избрании меры пресечения дознаватель, следователь или судья выносит постановление, а суд — определение, содержащее указание на преступление, в котором подозревается или обвиняется лицо, и основания для избрания этой меры пресечения."},{"n":"2","text":"Копия постановления или определения вручается лицу, в отношении которого оно вынесено, а также его защитнику или законному представителю по их просьбе."},{"n":"3","text":"Одновременно лицу разъясняется порядок обжалования решения об избрании меры пресечения."}]},{"n":"Статья 52","title":"Подписка о невыезде и надлежащем поведении","sub":[{"n":"1","text":"Подписка о невыезде и надлежащем поведении состоит в письменном обязательстве подозреваемого или обвиняемого:"},{"n":"1)","text":"не покидать постоянное или временное место жительства без разрешения дознавателя, следователя или суда;","lvl":1},{"n":"2)","text":"в назначенный срок являться по вызовам дознавателя, следователя и в суд;","lvl":1},{"n":"3)","text":"иным путем не препятствовать производству по уголовному делу.","lvl":1}]},{"n":"Статья 53","title":"Личное поручительство","sub":[{"n":"1","text":"Личное поручительство состоит в письменном обязательстве заслуживающего доверия лица о том, что оно ручается за выполнение подозреваемым или обвиняемым обязательств, предусмотренных пунктами 2 и 3 статьи 52 настоящего Кодекса."},{"n":"2","text":"Избрание личного поручительства допускается по письменному ходатайству одного или нескольких поручителей с согласия лица, в отношении которого дается поручительство."},{"n":"3","text":"В случае невыполнения поручителем своих обязательств на него может быть наложено денежное взыскание в размере до десяти тысяч рублей в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 54","title":"Наблюдение командования воинской части","sub":[{"n":"1","text":"Наблюдение командования воинской части за подозреваемым или обвиняемым, являющимся военнослужащим или гражданином, проходящим военные сборы, состоит в принятии мер, предусмотренных уставами Вооруженных Сил Российской Федерации."},{"n":"2","text":"Избрание этой меры пресечения допускается лишь с согласия подозреваемого, обвиняемого."}]},{"n":"Статья 55","title":"Присмотр за несовершеннолетним подозреваемым или обвиняемым","sub":[{"n":"1","text":"Присмотр состоит в обеспечении его надлежащего поведения родителями, опекунами, попечителями или другими заслуживающими доверия лицами, а также должностными лицами специализированного детского учреждения."},{"n":"2","text":"При избрании данной меры пресечения указанным лицам разъясняется существо подозрения или обвинения, а также их ответственность."}]},{"n":"Статья 56","title":"Запрет определенных действий","sub":[{"n":"1","text":"Запрет определенных действий заключается в возложении на подозреваемого или обвиняемого обязанностей своевременно являться по вызовам и соблюдать один или несколько запретов:"},{"n":"1)","text":"выходить в определенные периоды времени за пределы жилого помещения;","lvl":1},{"n":"2)","text":"находиться в определенных местах, ближе установленного расстояния до определенных объектов;","lvl":1},{"n":"3)","text":"общаться с определенными лицами;","lvl":1},{"n":"4)","text":"отправлять и получать почтово-телеграфные отправления;","lvl":1},{"n":"5)","text":"использовать средства связи и информационно-телекоммуникационную сеть «Интернет»;","lvl":1},{"n":"6)","text":"управлять автомобилем или иным транспортным средством.","lvl":1}]},{"n":"Статья 57","title":"Залог","sub":[{"n":"1","text":"Залог состоит во внесении или в передаче подозреваемым, обвиняемым либо другим физическим или юридическим лицом на стадии предварительного расследования в орган, в производстве которого находится уголовное дело, недвижимого имущества и движимого имущества в виде денег, ценностей и допущенных к публичному обращению в Российской Федерации акций и облигаций в целях обеспечения явки подозреваемого либо обвиняемого и предупреждения совершения им новых преступлений."}]},{"n":"Статья 58","title":"Домашний арест","sub":[{"n":"1","text":"Домашний арест заключается в нахождении подозреваемого или обвиняемого в полной либо частичной изоляции от общества в жилом помещении, в котором он проживает в качестве собственника, нанимателя либо на иных законных основаниях, с возложением ограничений и запретов, предусмотренных настоящим Кодексом."}]},{"n":"Статья 59","title":"Заключение под стражу","sub":[{"n":"1","text":"Заключение под стражу в качестве меры пресечения применяется по судебному решению в отношении подозреваемого или обвиняемого в совершении преступлений, за которые уголовным законом предусмотрено наказание в виде лишения свободы на срок свыше трех лет при невозможности применения иной, более мягкой, меры пресечения."},{"n":"2","text":"В исключительных случаях эта мера пресечения может быть избрана в отношении подозреваемого или обвиняемого в совершении преступления, за которое предусмотрено наказание в виде лишения свободы на срок до трех лет, при наличии одного из следующих обстоятельств:"},{"n":"1)","text":"подозреваемый или обвиняемый не имеет постоянного места жительства на территории Российской Федерации;","lvl":1},{"n":"2)","text":"его личность не установлена;","lvl":1},{"n":"3)","text":"им нарушена ранее избранная мера пресечения;","lvl":1},{"n":"4)","text":"он скрылся от органов предварительного расследования или от суда.","lvl":1},{"n":"3","text":"К несовершеннолетнему подозреваемому или обвиняемому заключение под стражу может быть применено в случае, если он подозревается или обвиняется в совершении тяжкого или особо тяжкого преступления. В исключительных случаях — в совершении преступления средней тяжести."},{"n":"4","text":"При необходимости избрания данной меры пресечения следователь с согласия руководителя следственного органа, а также дознаватель с согласия прокурора возбуждают перед судом соответствующее ходатайство."},{"n":"5","text":"Постановление о возбуждении ходатайства подлежит рассмотрению единолично судьей районного суда или военного суда соответствующего уровня с обязательным участием подозреваемого или обвиняемого, прокурора, защитника в течение 8 часов с момента поступления материалов в суд."},{"n":"6","text":"В судебном заседании вправе участвовать законный представитель несовершеннолетнего подозреваемого или обвиняемого, а также представитель органа, осуществляющего оперативно-розыскную деятельность, по ходатайству следователя или дознавателя."},{"n":"7","text":"Неявка сторон, своевременно извещенных о месте и времени судебного заседания, за исключением подозреваемого или обвиняемого, прокурора и защитника, не препятствует рассмотрению ходатайства."},{"n":"8","text":"По результатам рассмотрения ходатайства судья выносит одно из следующих постановлений:"},{"n":"1)","text":"об избрании в отношении подозреваемого или обвиняемого меры пресечения в виде заключения под стражу;","lvl":1},{"n":"2)","text":"об отказе в удовлетворении ходатайства;","lvl":1},{"n":"3)","text":"о продлении срока задержания подозреваемого.","lvl":1},{"n":"9","text":"Постановление судьи может быть обжаловано в апелляционном порядке в течение 3 суток со дня его вынесения."},{"n":"10","text":"Повторное обращение с ходатайством о заключении под стражу одного и того же лица по одному и тому же уголовному делу после вынесения судьей постановления об отказе в избрании этой меры пресечения возможно лишь при возникновении новых обстоятельств, обосновывающих необходимость применения данной меры."}]},{"n":"Статья 60","title":"Сроки содержания под стражей","sub":[{"n":"1","text":"Содержание под стражей при расследовании преступлений не может превышать 2 месяца."},{"n":"2","text":"В случае невозможности закончить предварительное следствие в срок до 2 месяцев и при отсутствии оснований для изменения или отмены меры пресечения этот срок может быть продлен судьей районного суда или военного суда соответствующего уровня на срок до 6 месяцев."},{"n":"3","text":"Дальнейшее продление сроков осуществляется в отношении лиц, обвиняемых в совершении тяжких и особо тяжких преступлений, — до 12 месяцев; в исключительных случаях — до 18 месяцев."},{"n":"4","text":"Срок содержания под стражей исчисляется с момента фактического задержания лица."},{"n":"5","text":"В срок содержания под стражей засчитывается время: задержания; домашнего ареста; принудительного нахождения в медицинском или психиатрическом стационаре по решению суда; времени, в течение которого лицо содержалось под стражей на территории иностранного государства по запросу о выдаче."},{"n":"6","text":"Ходатайство о продлении срока содержания под стражей рассматривается судьей с участием подозреваемого или обвиняемого, прокурора, защитника не позднее чем за 5 суток до истечения срока."},{"n":"7","text":"Постановление судьи о продлении срока содержания под стражей может быть обжаловано в апелляционном порядке в течение 3 суток."}]},{"n":"Статья 61","title":"Отмена или изменение меры пресечения","sub":[{"n":"1","text":"Мера пресечения отменяется, когда в ней отпадает необходимость, или изменяется на более строгую или более мягкую, когда изменяются основания для избрания меры пресечения."},{"n":"2","text":"Мера пресечения, избранная на основании судебного решения, отменяется или изменяется только судом."}]},{"h":"Глава 6. Ходатайства и жалобы"},{"n":"Статья 62","title":"Порядок заявления ходатайств","sub":[{"n":"1","text":"Ходатайства о производстве процессуальных действий или принятии процессуальных решений для установления обстоятельств, имеющих значение для уголовного дела, могут быть заявлены подозреваемым, обвиняемым, его защитником, законным представителем, потерпевшим, его представителем, гражданским истцом, гражданским ответчиком, их представителями, экспертом, специалистом, переводчиком."},{"n":"2","text":"Ходатайство может быть заявлено в письменной форме либо устно. Устное ходатайство заносится в протокол следственного действия или судебного заседания."}]},{"n":"Статья 63","title":"Сроки рассмотрения ходатайств","sub":[{"n":"1","text":"Ходатайство, заявленное в ходе досудебного производства, подлежит рассмотрению дознавателем, следователем, руководителем следственного органа, прокурором непосредственно после его заявления."},{"n":"2","text":"В случае невозможности немедленного рассмотрения ходатайства оно должно быть разрешено не позднее 3 суток со дня его заявления."}]},{"n":"Статья 64","title":"Порядок рассмотрения ходатайств","sub":[{"n":"1","text":"По результатам рассмотрения ходатайства дознаватель, следователь, руководитель следственного органа, прокурор выносят постановление о полном или частичном удовлетворении ходатайства либо об отказе в его удовлетворении."},{"n":"2","text":"Постановление об отказе в удовлетворении ходатайства должно быть мотивированным."},{"n":"3","text":"Отказ в удовлетворении ходатайства может быть обжалован в порядке, установленном настоящей главой."}]},{"n":"Статья 65","title":"Обжалование действий и решений должностных лиц","sub":[{"n":"1","text":"Действия (бездействие) и решения органа дознания, дознавателя, начальника подразделения дознания, начальника органа дознания, следователя, руководителя следственного органа и прокурора могут быть обжалованы в порядке, установленном настоящим Кодексом."},{"n":"2","text":"Жалоба может быть подана участниками уголовного судопроизводства, а также иными лицами в той части, в которой производимые процессуальные действия и принимаемые процессуальные решения затрагивают их интересы."}]},{"n":"Статья 66","title":"Судебный порядок рассмотрения жалоб","sub":[{"n":"1","text":"Постановления органа дознания, дознавателя, следователя, руководителя следственного органа об отказе в возбуждении уголовного дела, о прекращении уголовного дела, а равно иные действия (бездействие) и решения, которые способны причинить ущерб конституционным правам и свободам участников уголовного судопроизводства либо затруднить доступ граждан к правосудию, могут быть обжалованы в районный суд по месту совершения деяния, содержащего признаки преступления."},{"n":"2","text":"Жалоба может быть подана заявителем, его защитником, законным представителем или представителем непосредственно либо через дознавателя, следователя, руководителя следственного органа или прокурора."},{"n":"3","text":"Судья проверяет законность и обоснованность действий (бездействия) и решений не позднее чем через 14 суток со дня поступления жалобы в судебном заседании с участием заявителя и его защитника, законного представителя или представителя, прокурора, следователя, руководителя следственного органа."},{"n":"4","text":"По результатам рассмотрения жалобы судья выносит одно из следующих постановлений:"},{"n":"1)","text":"о признании действия (бездействия) или решения соответствующего должностного лица незаконным или необоснованным и о его обязанности устранить допущенное нарушение;","lvl":1},{"n":"2)","text":"об оставлении жалобы без удовлетворения.","lvl":1}]},{"h":"Глава 7. Возбуждение уголовного дела"},{"n":"Статья 67","title":"Поводы и основание для возбуждения уголовного дела","sub":[{"n":"1","text":"Поводами для возбуждения уголовного дела служат: заявление о преступлении, явка с повинной, рапорт об обнаружении признаков преступления."},{"n":"2","text":"Основанием для возбуждения уголовного дела является наличие достаточных данных, указывающих на признаки преступления."}]},{"n":"Статья 68","title":"Основания отказа в возбуждении уголовного дела или прекращения уголовного дела","sub":[{"n":"1","text":"Уголовное дело не может быть возбуждено, а возбужденное уголовное дело подлежит прекращению по следующим основаниям:"},{"n":"1)","text":"отсутствие события преступления;","lvl":1},{"n":"2)","text":"отсутствие в деянии состава преступления;","lvl":1},{"n":"3)","text":"истечение сроков давности уголовного преследования;","lvl":1},{"n":"4)","text":"смерть подозреваемого или обвиняемого (за исключением случаев реабилитации);","lvl":1},{"n":"5)","text":"отсутствие заявления потерпевшего, если дело возбуждается не иначе как по его заявлению.","lvl":1}]},{"n":"Статья 69","title":"Прекращение уголовного дела или возвращение уголовного дела прокурору в судебном заседании","sub":[{"n":"1","text":"Судья по ходатайству сторон или по собственной инициативе прекращает уголовное дело при наличии оснований, предусмотренных статьей 68 настоящего Кодекса, либо возвращает дело прокурору для устранения препятствий его рассмотрения судом."}]},{"n":"Статья 70","title":"Основания и порядок приостановления предварительного расследования","sub":[{"n":"1","text":"Предварительное расследование приостанавливается при наличии одного из следующих оснований:"},{"n":"1)","text":"лицо, подлежащее привлечению в качестве обвиняемого, не установлено;","lvl":1},{"n":"2)","text":"обвиняемый скрылся от следствия либо его местонахождение не установлено;","lvl":1},{"n":"3)","text":"местонахождение обвиняемого известно, однако реальная возможность его участия в деле отсутствует;","lvl":1},{"n":"4)","text":"временное тяжелое заболевание обвиняемого, удостоверенное врачом.","lvl":1}]},{"n":"Статья 71","title":"Действия следователя после приостановления предварительного расследования","sub":[{"n":"1","text":"Приостановив предварительное расследование, следователь принимает меры по установлению лица, совершившего преступление, розыску скрывшегося обвиняемого, а также по обнаружению его имущества."}]},{"n":"Статья 72","title":"Порядок розыска подозреваемого, обвиняемого","sub":[{"n":"1","text":"При неизвестности местонахождения подозреваемого или обвиняемого следователь поручает его розыск органам дознания, о чем указывает в постановлении о приостановлении расследования или выносит отдельное постановление."}]},{"n":"Статья 73","title":"Возобновление приостановленного предварительного расследования","sub":[{"n":"1","text":"Приостановленное предварительное расследование возобновляется мотивированным постановлением следователя (дознавателя) после того, как отпали основания для его приостановления либо возникла необходимость производства следственных действий."}]},{"n":"Статья 74","title":"Выделение уголовного дела","sub":[{"n":"1","text":"Следователь вправе выделить из уголовного дела в отдельное производство другое уголовное дело в отношении отдельных подозреваемых (обвиняемых) по уголовным делам о преступлениях, совершенных в соучастии, если это не отразится на всесторонности и объективности расследования."}]},{"n":"Статья 75","title":"Выделение в отдельное производство материалов уголовного дела","sub":[{"n":"1","text":"В случае если в ходе расследования выявлено новое преступление, не связанное с расследуемым, следователь выделяет соответствующие материалы и направляет их для принятия решения о возбуждении нового дела."}]},{"n":"Статья 76","title":"Соединение уголовных дел","sub":[{"n":"1","text":"В одном производстве могут быть соединены уголовные дела в отношении нескольких лиц, совершивших одно или несколько преступлений в соучастии, либо в отношении одного лица, совершившего несколько преступлений."}]},{"n":"Статья 77","title":"Заявление о преступлении","sub":[{"n":"1","text":"Заявление о преступлении может быть сделано в устном или письменном виде. Устное заявление заносится в протокол. Заявитель предупреждается об уголовной ответственности за заведомо ложный донос."}]},{"n":"Статья 78","title":"Рапорт об обнаружении признаков преступления","sub":[{"n":"1","text":"Сообщение о совершенном или готовящемся преступлении, полученное из иных источников, чем заявления, принимается лицом, получившим его, и оформляется рапортом об обнаружении признаков преступления."}]},{"n":"Статья 79","title":"Порядок возбуждения уголовного дела","sub":[{"n":"1","text":"При наличии повода и основания следователь, орган дознания или дознаватель в пределах своей компетенции выносят постановление о возбуждении уголовного дела, копия которого незамедлительно направляется прокурору."}]},{"n":"Статья 80","title":"Порядок рассмотрения сообщения о преступлении","sub":[{"n":"1","text":"Сообщение о преступлении может быть сделано в устном или письменном виде."},{"n":"2","text":"Письменное сообщение о преступлении должно быть подписано заявителем."},{"n":"3","text":"Анонимное сообщение о преступлении не может служить поводом для возбуждения уголовного дела."}]},{"n":"Статья 81","title":"Сроки проверки сообщения о преступлении","sub":[{"n":"1","text":"По сообщению о преступлении, распространенному в средствах массовой информации, проверка производится по указанию прокурора."},{"n":"2","text":"Решение по результатам рассмотрения сообщения о преступлении должно быть принято в срок не позднее 3 суток со дня поступления указанного сообщения."},{"n":"3","text":"Руководитель следственного органа, начальник органа дознания вправе по мотивированному ходатайству следователя, дознавателя продлить до 10 суток срок, установленный частью второй настоящей статьи."},{"n":"4","text":"При необходимости производства документальных проверок, ревизий, исследований документов, предметов, трупов руководитель следственного органа по ходатайству следователя, а прокурор по ходатайству дознавателя вправе продлить этот срок до 30 суток."}]},{"n":"Статья 82","title":"Решение, принимаемое по сообщению о преступлении","sub":[{"n":"1","text":"По результатам рассмотрения сообщения о преступлении орган дознания, дознаватель, следователь, руководитель следственного органа принимает одно из следующих решений:"},{"n":"1)","text":"о возбуждении уголовного дела;","lvl":1},{"n":"2)","text":"об отказе в возбуждении уголовного дела;","lvl":1},{"n":"3)","text":"о передаче сообщения по подследственности или в суд.","lvl":1},{"n":"2","text":"О принятом решении сообщается заявителю. Заявителю разъясняются его право обжаловать данное решение и порядок обжалования."}]},{"n":"Статья 83","title":"Отказ в возбуждении уголовного дела","sub":[{"n":"1","text":"При отсутствии основания для возбуждения уголовного дела руководитель следственного органа, следователь, орган дознания, дознаватель выносит постановление об отказе в возбуждении уголовного дела."},{"n":"2","text":"Копия постановления об отказе в возбуждении уголовного дела в течение 24 часов с момента его вынесения направляется заявителю и прокурору."},{"n":"3","text":"Отказ в возбуждении уголовного дела может быть обжалован прокурору или в суд в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 84","title":"Возбуждение уголовного дела публичного обвинения","sub":[{"n":"1","text":"При наличии повода и основания, предусмотренных статьей 67 настоящего Кодекса, орган дознания, дознаватель, следователь, руководитель следственного органа возбуждают уголовное дело, о чем выносится соответствующее постановление."},{"n":"2","text":"В постановлении о возбуждении уголовного дела указываются: дата, время и место его вынесения; кем оно вынесено; повод и основание для возбуждения; пункт, часть, статья уголовного закона, на основании которых возбуждается дело."},{"n":"3","text":"Копия постановления о возбуждении уголовного дела незамедлительно направляется прокурору."}]},{"n":"Статья 85","title":"Возбуждение уголовного дела частно-публичного обвинения","sub":[{"n":"1","text":"Уголовные дела о преступлениях, указанных в законе, считаются уголовными делами частно-публичного обвинения."},{"n":"2","text":"Указанные дела возбуждаются не иначе как по заявлению потерпевшего, но производство по ним ведется в общем порядке."}]},{"n":"Статья 86","title":"Возбуждение уголовного дела частного обвинения","sub":[{"n":"1","text":"Уголовные дела о преступлениях, указанных в законе, считаются уголовными делами частного обвинения."},{"n":"2","text":"Указанные дела возбуждаются не иначе как по заявлению потерпевшего и подлежат прекращению в связи с примирением потерпевшего с обвиняемым."}]},{"h":"Глава 8. Общие условия предварительного расследования"},{"n":"Статья 87","title":"Формы предварительного расследования","sub":[{"n":"1","text":"Предварительное расследование осуществляется в форме предварительного следствия либо в форме дознания."}]},{"n":"Статья 88","title":"Подследственность","sub":[{"n":"1","text":"Производство предварительного расследования осуществляется тем органом (Следственный комитет, ФСБ, МВД), к чьей предметной и территориальной подследственности законодательством отнесено данное преступление."}]},{"n":"Статья 89","title":"Начало производства предварительного расследования","sub":[{"n":"1","text":"Предварительное расследование начинается с момента возбуждения уголовного дела, о чем следователь или дознаватель делает отметку в постановлении."}]},{"n":"Статья 90","title":"Дознание","sub":[{"n":"1","text":"Дознание производится по делам о преступлениях небольшой и средней тяжести в укороченные сроки, по истечении которых составляется обвинительный акт или обвинительное постановление."}]},{"n":"Статья 91","title":"Обязательность рассмотрения ходатайств","sub":[{"n":"1","text":"Дознаватель, следователь, руководитель следственного органа обязаны рассмотреть каждое заявленное по уголовному делу ходатайство."},{"n":"2","text":"Об удовлетворении ходатайства либо о полном или частичном отказе в его удовлетворении дознаватель, следователь, руководитель следственного органа выносят постановление."}]},{"n":"Статья 92","title":"Недопустимость разглашения данных предварительного расследования","sub":[{"n":"1","text":"Данные предварительного расследования могут быть преданы гласности лишь с разрешения следователя или дознавателя и только в том объеме, в каком ими это будет признано допустимым."},{"n":"2","text":"Следователь или дознаватель предупреждает участников уголовного судопроизводства о недопустимости разглашения данных предварительного расследования без его разрешения, о чем берется подписка."}]},{"n":"Статья 93","title":"Соединение уголовных дел","sub":[{"n":"1","text":"В одном производстве могут быть соединены уголовные дела в отношении:"},{"n":"1)","text":"нескольких лиц, совершивших одно или несколько преступлений в соучастии;","lvl":1},{"n":"2)","text":"одного лица, совершившего несколько преступлений;","lvl":1},{"n":"3)","text":"лица, обвиняемого в заранее не обещанном укрывательстве преступлений, расследуемых по этим уголовным делам.","lvl":1},{"n":"2","text":"Соединение уголовных дел производится на основании постановления руководителя следственного органа, а также прокурора."}]},{"n":"Статья 94","title":"Выделение уголовного дела","sub":[{"n":"1","text":"Следователь вправе выделить из уголовного дела в отдельное производство другое уголовное дело в отношении:"},{"n":"1)","text":"отдельных подозреваемых или обвиняемых по уголовным делам о преступлениях, совершенных в соучастии;","lvl":1},{"n":"2)","text":"несовершеннолетнего подозреваемого или обвиняемого, привлеченного к уголовной ответственности вместе с совершеннолетними обвиняемыми;","lvl":1},{"n":"3)","text":"иных лиц, подозреваемых или обвиняемых в совершении преступления, не связанного с расследуемым.","lvl":1},{"n":"2","text":"Выделение уголовного дела производится на основании постановления следователя."}]},{"n":"Статья 95","title":"Выделение в отдельное производство материалов уголовного дела","sub":[{"n":"1","text":"В случае если в ходе предварительного расследования выявлено новое преступление, не связанное с расследуемым, следователь выделяет соответствующие материалы и направляет их руководителю следственного органа для принятия решения о возбуждении уголовного дела."}]},{"n":"Статья 96","title":"Начало производства предварительного расследования","sub":[{"n":"1","text":"Предварительное расследование начинается с момента возбуждения уголовного дела, о чем следователь, дознаватель выносит соответствующее постановление."},{"n":"2","text":"В постановлении о возбуждении уголовного дела указывается о принятии его к производству."}]},{"n":"Статья 97","title":"Производство неотложных следственных действий","sub":[{"n":"1","text":"При наличии признаков преступления, по которому производство предварительного следствия обязательно, орган дознания в порядке, установленном настоящим Кодексом, возбуждает уголовное дело и производит неотложные следственные действия."},{"n":"2","text":"Неотложные следственные действия производятся в срок не позднее 10 суток со дня возбуждения уголовного дела."}]},{"n":"Статья 98","title":"Окончание предварительного расследования","sub":[{"n":"1","text":"Производство предварительного расследования оканчивается:"},{"n":"1)","text":"направлением уголовного дела прокурору с обвинительным заключением;","lvl":1},{"n":"2)","text":"направлением уголовного дела в суд с обвинительным актом или обвинительным постановлением;","lvl":1},{"n":"3)","text":"прекращением уголовного дела.","lvl":1}]},{"n":"Статья 99","title":"Восстановление уголовных дел","sub":[{"n":"1","text":"Восстановление утраченного уголовного дела либо его материалов производится по постановлению руководителя следственного органа, начальника органа дознания на основании сохранившихся копий."}]},{"n":"Статья 100","title":"Обязательность удовлетворения ходатайств","sub":[{"n":"1","text":"Дознаватель, следователь, руководитель следственного органа, прокурор обязаны рассмотреть каждое заявленное по уголовному делу ходатайство и принять по нему мотивированное решение."}]},{"h":"Глава 9. Предварительное следствие"},{"n":"Статья 101","title":"Производство предварительного следствия","sub":[{"n":"1","text":"Предварительное следствие производится следователями Следственного комитета Российской Федерации, органов внутренних дел Российской Федерации и органов федеральной службы безопасности Российской Федерации."}]},{"n":"Статья 102","title":"Производство предварительного следствия следственной группой","sub":[{"n":"1","text":"Производство предварительного следствия по сложному или большому по объему уголовному делу может быть поручено следственной группе, о чем выносится отдельное постановление."}]},{"n":"Статья 103","title":"Общие правила производства следственных действий","sub":[{"n":"1","text":"При производстве следственных действий не допускается применение насилия, угроз и иных незаконных мер, а также создание опасности для жизни и здоровья участников."},{"n":"2","text":"В ночное время следственные действия не допускаются, за исключением случаев, не терпящих отлагательства."},{"n":"3","text":"Следственные действия производятся на основании постановления следователя."},{"n":"4","text":"При производстве следственных действий могут применяться технические средства и способы обнаружения, фиксации и изъятия следов преступления."}]},{"n":"Статья 104","title":"Судебный порядок получения разрешения на производство следственного действия","sub":[{"n":"1","text":"Следователь с согласия руководителя следственного органа, а дознаватель с согласия прокурора возбуждают перед судьей ходатайство о производстве следственного действия, требующего судебного решения:"},{"n":"1)","text":"о производстве осмотра жилища при отсутствии согласия проживающих в нем лиц;","lvl":1},{"n":"2)","text":"о производстве обыска в жилище;","lvl":1},{"n":"3)","text":"о производстве выемки в жилище;","lvl":1},{"n":"4)","text":"о наложении ареста на почтово-телеграфные отправления;","lvl":1},{"n":"5)","text":"о контроле и записи телефонных и иных переговоров.","lvl":1},{"n":"2","text":"Ходатайство подлежит рассмотрению единолично судьей районного суда или военного суда соответствующего уровня не позднее 24 часов с момента поступления материалов."}]},{"n":"Статья 105","title":"Протокол следственного действия","sub":[{"n":"1","text":"Протокол следственного действия составляется в ходе его производства или непосредственно после его окончания."},{"n":"2","text":"Протокол предъявляется для ознакомления всем лицам, участвовавшим в следственном действии."},{"n":"3","text":"Протокол подписывается следователем и всеми лицами, участвовавшими в следственном действии."},{"n":"4","text":"К протоколу прилагаются фотографические негативы и снимки, киноленты, диапозитивы, фонограммы, видеозаписи, чертежи, планы, схемы, слепки и оттиски следов."}]},{"n":"Статья 106","title":"Удостоверение факта отказа от подписи","sub":[{"n":"1","text":"В случае отказа лица, участвовавшего в следственном действии, подписать протокол, следователь вносит в протокол соответствующую запись, которая удостоверяется подписью следователя и понятых, если они участвуют."}]},{"n":"Статья 107","title":"Участие понятых","sub":[{"n":"1","text":"Понятые участвуют в производстве следственных действий в случаях, предусмотренных настоящим Кодексом."},{"n":"2","text":"Понятые удостоверяют факт производства следственного действия, его содержание и результаты."},{"n":"3","text":"Понятые вправе делать замечания по поводу произведенных действий, которые подлежат занесению в протокол."}]},{"n":"Статья 108","title":"Применение технических средств","sub":[{"n":"1","text":"При производстве следственных действий могут применяться технические средства для обнаружения, фиксации и изъятия следов преступления и вещественных доказательств."},{"n":"2","text":"Применение технических средств отмечается в протоколе следственного действия."}]},{"n":"Статья 109","title":"Осмотр","sub":[{"n":"1","text":"Следователь производит осмотр места происшествия, местности, жилища, предметов и документов в целях обнаружения следов преступления и выяснения других обстоятельств, имеющих значение для уголовного дела."},{"n":"2","text":"В случаях, не терпящих отлагательства, осмотр места происшествия может быть произведен до возбуждения уголовного дела."},{"n":"3","text":"Осмотр жилища при отсутствии согласия проживающих в нем лиц производится на основании судебного решения."}]},{"n":"Статья 110","title":"Осмотр трупа. Эксгумация","sub":[{"n":"1","text":"Следователь производит осмотр трупа с участием судебно-медицинского эксперта, а при невозможности его участия — врача."},{"n":"2","text":"При необходимости извлечения трупа из места захоронения следователь выносит постановление об эксгумации."}]},{"n":"Статья 111","title":"Освидетельствование","sub":[{"n":"1","text":"Для обнаружения на теле человека особых примет, следов преступления, телесных повреждений, выявления состояния опьянения или иных свойств и состояний, имеющих значение для уголовного дела, может быть произведено освидетельствование."},{"n":"2","text":"Освидетельствование производится следователем с участием врача или иного специалиста."}]},{"n":"Статья 112","title":"Следственный эксперимент","sub":[{"n":"1","text":"В целях проверки и уточнения данных, имеющих значение для уголовного дела, следователь вправе произвести следственный эксперимент путем воспроизведения действий, обстановки или иных обстоятельств определенного события."},{"n":"2","text":"Производство следственного эксперимента допускается, если не создается опасность для здоровья участвующих в нем лиц."}]},{"n":"Статья 113","title":"Обыск","sub":[{"n":"1","text":"Основанием для производства обыска является наличие достаточных данных полагать, что в каком-либо месте или у какого-либо лица могут находиться орудия, оборудование или иные предметы, имеющие значение для уголовного дела."},{"n":"2","text":"Обыск производится на основании постановления следователя."},{"n":"3","text":"Обыск в жилище производится на основании судебного решения. В исключительных случаях, не терпящих отлагательства, обыск в жилище может быть произведен на основании постановления следователя с уведомлением судьи и прокурора в течение 24 часов."},{"n":"4","text":"При производстве обыска участвуют: лицо, у которого производится обыск, или совершеннолетние члены его семьи; защитник, если он участвует в деле; понятые; специалист, если он необходим."},{"n":"5","text":"Лицам, участвующим в обыске, разъясняются их права и обязанности, а также порядок производства обыска."},{"n":"6","text":"При производстве обыска следователь вправе: вскрывать помещения, если владелец отказывается добровольно их открыть; запретить лицам, находящимся в помещении, покидать его до окончания обыска; запретить лицам, находящимся в помещении, общаться друг с другом до окончания обыска."},{"n":"7","text":"При производстве обыска следователь обязан: предъявить постановление или судебное решение; предложить добровольно выдать подлежащие изъятию предметы; вести протокол; обеспечить сохранность имущества; вручить копию протокола лицу, у которого производился обыск."},{"n":"8","text":"Изъятые предметы и документы предъявляются участвующим лицам и описываются в протоколе с указанием их наименования, количества, меры, веса, индивидуальных признаков и по возможности стоимости."},{"n":"9","text":"В протоколе указываются: место и дата производства обыска; время начала и окончания; должность и фамилия следователя; основания производства; состав участвующих лиц; действия следователя; изъятые предметы и документы; заявления и замечания участвующих лиц."},{"n":"10","text":"Копия протокола вручается под расписку лицу, у которого производился обыск, или совершеннолетним членам его семьи. При отсутствии таких лиц копия направляется для вручения по месту жительства или работы."},{"n":"11","text":"Обыск может быть обжалован прокурору или в суд в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 114","title":"Выемка","sub":[{"n":"1","text":"При необходимости изъятия определенных предметов и документов, имеющих значение для уголовного дела, следователь производит выемку."},{"n":"2","text":"Выемка производится на основании постановления следователя."},{"n":"3","text":"Выемка предметов и документов, содержащих государственную или иную охраняемую законом тайну, производится с санкции прокурора."}]},{"n":"Статья 115","title":"Наложение ареста на почтово-телеграфные отправления","sub":[{"n":"1","text":"При наличии достаточных данных полагать, что предметы, документы или сведения, имеющие значение для уголовного дела, могут содержаться в почтово-телеграфных отправлениях, следователь возбуждает перед судом ходатайство о наложении ареста на почтово-телеграфные отправления."},{"n":"2","text":"Арест на почтово-телеграфные отправления налагается на основании судебного решения."}]},{"n":"Статья 116","title":"Контроль и запись переговоров","sub":[{"n":"1","text":"При наличии достаточных данных полагать, что переговоры подозреваемого, обвиняемого и других лиц могут содержать сведения, имеющие значение для уголовного дела, их контроль и запись допускаются только на основании судебного решения."},{"n":"2","text":"Контроль и запись переговоров производятся в отношении лиц, подозреваемых или обвиняемых в совершении преступлений средней тяжести, тяжких или особо тяжких преступлений."}]},{"n":"Статья 117","title":"Получение информации о соединениях между абонентами","sub":[{"n":"1","text":"При наличии достаточных данных полагать, что информация о соединениях между абонентами и абонентскими устройствами имеет значение для уголовного дела, следователь возбуждает перед судом ходатайство о получении указанной информации."},{"n":"2","text":"Получение информации о соединениях производится на основании судебного решения."}]},{"n":"Статья 118","title":"Допрос и порядок его проведения","sub":[{"n":"1","text":"Допрос проводится по месту производства предварительного расследования."},{"n":"2","text":"Допрос не может длиться непрерывно более 4 часов. Продолжение допроса допускается после перерыва не менее чем на один час. Общая продолжительность допроса в течение дня не должна превышать 8 часов."},{"n":"3","text":"Следователь допрашивает лицо с соблюдением требований, установленных настоящим Кодексом."},{"n":"4","text":"Перед началом допроса следователь: удостоверяется в личности допрашиваемого; разъясняет ему права и обязанности; предупреждает об ответственности за отказ от дачи показаний и за дачу заведомо ложных показаний, если это предусмотрено законом."},{"n":"5","text":"В допросе несовершеннолетнего участвуют: защитник; законный представитель; педагог или психолог, если допрашиваемый не достиг 16 лет."},{"n":"6","text":"В допросе лица, не владеющего языком, на котором ведется производство, участвует переводчик."},{"n":"7","text":"По окончании допроса составляется протокол, в котором указываются: место и дата; время начала и окончания; должность и фамилия следователя; данные о допрашиваемом; разъяснение прав; показания; заявления и замечания."},{"n":"8","text":"Протокол предъявляется допрашиваемому для ознакомления. По просьбе допрашиваемого ему разъясняется порядок внесения замечаний."},{"n":"9","text":"Допрашиваемый вправе: отказаться подписать протокол с указанием мотивов отказа; внести в протокол замечания; потребовать дополнения протокола."},{"n":"10","text":"Отказ от дачи показаний и дача заведомо ложных показаний влекут ответственность в соответствии с законодательством Российской Федерации."}]},{"n":"Статья 119","title":"Очная ставка","sub":[{"n":"1","text":"Следователь вправе произвести очную ставку между ранее допрошенными лицами в целях устранения существенных противоречий в их показаниях."},{"n":"2","text":"Очная ставка производится в присутствии защитника, если он участвует в уголовном деле."}]},{"n":"Статья 120","title":"Предъявление для опознания","sub":[{"n":"1","text":"Следователь может предъявить для опознания лицу, ранее допрошенному об обстоятельствах, при которых оно наблюдало предмет или лицо, соответствующий предмет или лицо."},{"n":"2","text":"Опознающие предварительно допрашиваются об обстоятельствах, при которых они наблюдали соответствующий предмет или лицо."},{"n":"3","text":"Предъявление для опознания производится с участием понятых."}]},{"n":"Статья 121","title":"Проверка показаний на месте","sub":[{"n":"1","text":"В целях установления новых обстоятельств, имеющих значение для уголовного дела, следователь вправе произвести проверку показаний ранее допрошенного лица путем воспроизведения им обстановки и обстоятельств события."},{"n":"2","text":"Проверка показаний на месте производится с участием понятых."}]},{"n":"Статья 122","title":"Назначение и производство судебной экспертизы","sub":[{"n":"1","text":"Судебная экспертиза назначается в случаях, когда при производстве по делу необходимы специальные знания в науке, технике, искусстве или ремесле."},{"n":"2","text":"Назначение экспертизы оформляется постановлением следователя."},{"n":"3","text":"Следователь вправе присутствовать при производстве судебной экспертизы."}]},{"n":"Статья 123","title":"Заключение и показания эксперта","sub":[{"n":"1","text":"Заключение эксперта — представленные в письменном виде содержание исследования и выводы по вопросам, поставленным перед экспертом."},{"n":"2","text":"Эксперт может быть допрошен для разъяснения данного им заключения в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 124","title":"Получение образцов для сравнительного исследования","sub":[{"n":"1","text":"Следователь вправе получить образцы почерка или иные образцы для сравнительного исследования у подозреваемого, обвиняемого, свидетеля, потерпевшего."},{"n":"2","text":"О получении образцов составляется протокол."}]},{"n":"Статья 125","title":"Помещение в медицинский или психиатрический стационар","sub":[{"n":"1","text":"Помещение подозреваемого или обвиняемого, не содержащегося под стражей, в медицинский или психиатрический стационар для производства судебной экспертизы производится на основании судебного решения."},{"n":"2","text":"Помещение в психиатрический стационар производится при необходимости стационарного обследования."}]},{"n":"Статья 126","title":"Продление сроков предварительного следствия","sub":[{"n":"1","text":"Срок предварительного следствия, установленный законом (по общему правилу 2 месяца), может быть продлен руководителем соответствующего следственного органа при наличии обоснованной необходимости в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 127","title":"Порядок работы с преступлениями с истекающим сроком давности","sub":[{"n":"1","text":"При истечении сроков давности уголовного преследования дело подлежит прекращению в соответствии со статьей 68 настоящего Кодекса, за исключением случаев, когда подозреваемый или обвиняемый возражает против прекращения по данному нереабилитирующему основанию. В этом случае производство продолжается в обычном порядке."}]},{"h":"Глава 10. Приостановление и возобновление предварительного расследования"},{"n":"Статья 128","title":"Основания приостановления предварительного расследования","sub":[{"n":"1","text":"Предварительное расследование приостанавливается при наличии одного из следующих оснований:"},{"n":"1)","text":"лицо, подлежащее привлечению в качестве обвиняемого, не установлено;","lvl":1},{"n":"2)","text":"обвиняемый скрылся от следствия либо его местонахождение не установлено;","lvl":1},{"n":"3)","text":"местонахождение обвиняемого известно, однако реальная возможность его участия в деле отсутствует;","lvl":1},{"n":"4)","text":"временное тяжелое заболевание обвиняемого, удостоверенное врачом.","lvl":1}]},{"n":"Статья 129","title":"Порядок приостановления предварительного расследования","sub":[{"n":"1","text":"О приостановлении предварительного расследования следователь выносит постановление."},{"n":"2","text":"Копия постановления направляется прокурору."}]},{"n":"Статья 130","title":"Действия следователя после приостановления","sub":[{"n":"1","text":"Приостановив предварительное расследование, следователь принимает меры по установлению лица, совершившего преступление, розыску скрывшегося обвиняемого, а также по обнаружению его имущества."}]},{"n":"Статья 131","title":"Розыск подозреваемого, обвиняемого","sub":[{"n":"1","text":"При неизвестности местонахождения подозреваемого или обвиняемого следователь поручает его розыск органам дознания."},{"n":"2","text":"О розыске указывается в постановлении о приостановлении расследования или выносится отдельное постановление."}]},{"n":"Статья 132","title":"Возобновление приостановленного предварительного расследования","sub":[{"n":"1","text":"Приостановленное предварительное расследование возобновляется мотивированным постановлением следователя после того, как отпали основания для его приостановления либо возникла необходимость производства следственных действий."}]},{"h":"Глава 11. Окончание предварительного следствия"},{"n":"Статья 133","title":"Окончание предварительного следствия с обвинительным заключением","sub":[{"n":"1","text":"Произведя все следственные действия и признав собранные доказательства достаточными для составления обвинительного заключения, следователь уведомляет об этом обвиняемого и разъясняет ему право на ознакомление со всеми материалами уголовного дела."}]},{"n":"Статья 134","title":"Ознакомление потерпевшего, гражданского истца, гражданского ответчика с материалами дела","sub":[{"n":"1","text":"По ходатайству потерпевшего, гражданского истца, гражданского ответчика и их представителей следователь знакомит этих лиц с материалами уголовного дела полностью или частично в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 135","title":"Ознакомление обвиняемого и его защитника с материалами дела","sub":[{"n":"1","text":"После выполнения требований статьи 134 настоящего Кодекса следователь предъявляет обвиняемому и его защитнику подшитые и пронумерованные материалы уголовного дела."},{"n":"2","text":"Обвиняемый и его защитник не могут ограничиваться во времени, необходимом им для ознакомления с материалами уголовного дела."}]},{"n":"Статья 136","title":"Протокол ознакомления с материалами уголовного дела","sub":[{"n":"1","text":"Об ознакомлении обвиняемого и его защитника с материалами уголовного дела составляется протокол."},{"n":"2","text":"В протоколе указываются: дата и место составления; сведения о лицах, ознакомившихся с материалами; время ознакомления; заявления и ходатайства."}]},{"n":"Статья 137","title":"Обвинительное заключение","sub":[{"n":"1","text":"Обвинительное заключение — процессуальный документ, в котором подводятся итоги предварительного следствия и формулируется обвинение."},{"n":"2","text":"В обвинительном заключении указываются:"},{"n":"1)","text":"сведения об обвиняемом;","lvl":1},{"n":"2)","text":"сущность обвинения, место и время совершения преступления;","lvl":1},{"n":"3)","text":"формулировка предъявленного обвинения;","lvl":1},{"n":"4)","text":"перечень доказательств, подтверждающих обвинение;","lvl":1},{"n":"5)","text":"перечень доказательств, на которые ссылается сторона защиты;","lvl":1},{"n":"6)","text":"обстоятельства, смягчающие и отягчающие наказание;","lvl":1},{"n":"7)","text":"данные о потерпевшем, характере и размере вреда, причиненного ему преступлением.","lvl":1},{"n":"3","text":"Обвинительное заключение подписывается следователем и направляется прокурору."}]},{"n":"Статья 138","title":"Решения прокурора по уголовному делу, поступившему с обвинительным заключением","sub":[{"n":"1","text":"Прокурор рассматривает поступившее от следователя уголовное дело с обвинительным заключением и в течение установленного срока принимает одно из решений:"},{"n":"1)","text":"об утверждении обвинительного заключения и о направлении уголовного дела в суд;","lvl":1},{"n":"2)","text":"о возвращении уголовного дела следователю для производства дополнительного следствия;","lvl":1},{"n":"3)","text":"о прекращении уголовного дела.","lvl":1}]},{"n":"Статья 139","title":"Направление уголовного дела в суд","sub":[{"n":"1","text":"После утверждения обвинительного заключения прокурор направляет уголовное дело в суд, о чем уведомляет обвиняемого, его защитника и потерпевшего."}]},{"h":"Глава 12. Дознание"},{"n":"Статья 140","title":"Порядок производства дознания","sub":[{"n":"1","text":"Дознание производится по делам о преступлениях небольшой и средней тяжести в укороченные сроки."},{"n":"2","text":"Дознание производится дознавателем, а по делам, по которым производство предварительного следствия не обязательно, — также следователем."}]},{"n":"Статья 141","title":"Сроки дознания","sub":[{"n":"1","text":"Дознание производится в срок не более 30 суток со дня возбуждения уголовного дела."},{"n":"2","text":"Этот срок может быть продлен прокурором до 60 суток."},{"n":"3","text":"В необходимых случаях, в том числе связанных с производством судебной экспертизы, срок дознания может быть продлен прокурором до 6 месяцев."}]},{"n":"Статья 142","title":"Обвинительный акт","sub":[{"n":"1","text":"По окончании дознания дознаватель составляет обвинительный акт."},{"n":"2","text":"В обвинительном акте указываются: дата и место его составления; должность, фамилия и инициалы дознавателя; данные о лице, привлекаемом к уголовной ответственности; сущность обвинения; формулировка обвинения; перечень доказательств; данные о потерпевшем; данные о гражданском истце и гражданском ответчике."},{"n":"3","text":"Обвинительный акт утверждается начальником органа дознания и направляется прокурору."}]},{"n":"Статья 143","title":"Обвинительное постановление","sub":[{"n":"1","text":"По окончании дознания в сокращенной форме дознаватель составляет обвинительное постановление."},{"n":"2","text":"Обвинительное постановление должно содержать указание на обстоятельства, установленные в ходе дознания."}]},{"n":"Статья 144","title":"Окончание дознания","sub":[{"n":"1","text":"Прокурор рассматривает уголовное дело, поступившее с обвинительным актом или обвинительным постановлением, и принимает одно из решений:"},{"n":"1)","text":"об утверждении обвинительного акта (постановления) и о направлении уголовного дела в суд;","lvl":1},{"n":"2)","text":"о возвращении уголовного дела для производства дополнительного дознания;","lvl":1},{"n":"3)","text":"о прекращении уголовного дела.","lvl":1}]},{"h":"Часть 3. Судебное производство"},{"h":"Глава 13. Подготовка к судебному заседанию"},{"n":"Статья 145","title":"Полномочия судьи по поступившему в суд уголовному делу","sub":[{"n":"1","text":"По поступившему уголовному делу судья принимает одно из следующих решений:"},{"n":"1)","text":"о направлении уголовного дела по подсудности;","lvl":1},{"n":"2)","text":"о назначении предварительного слушания;","lvl":1},{"n":"3)","text":"о назначении судебного заседания.","lvl":1}]},{"n":"Статья 146","title":"Вопросы, подлежащие выяснению","sub":[{"n":"1","text":"При разрешении вопроса о назначении судебного заседания судья выясняет:"},{"n":"1)","text":"подсудно ли уголовное дело данному суду;","lvl":1},{"n":"2)","text":"вручены ли копии обвинительного заключения или обвинительного акта;","lvl":1},{"n":"3)","text":"подлежит ли отмене или изменению избранная мера пресечения;","lvl":1},{"n":"4)","text":"подлежат ли удовлетворению заявленные ходатайства и поданные жалобы.","lvl":1}]},{"n":"Статья 147","title":"Предварительное слушание","sub":[{"n":"1","text":"Предварительное слушание проводится судьей единолично в закрытом судебном заседании с участием сторон."},{"n":"2","text":"Предварительное слушание проводится при наличии оснований, предусмотренных статьей 148 настоящего Кодекса."}]},{"n":"Статья 148","title":"Основания проведения предварительного слушания","sub":[{"n":"1","text":"Предварительное слушание проводится:"},{"n":"1)","text":"при наличии ходатайства стороны об исключении доказательства;","lvl":1},{"n":"2)","text":"при наличии основания для возвращения уголовного дела прокурору;","lvl":1},{"n":"3)","text":"при наличии основания для приостановления или прекращения уголовного дела;","lvl":1},{"n":"4)","text":"для решения вопроса о рассмотрении уголовного дела судом с участием присяжных заседателей.","lvl":1}]},{"n":"Статья 149","title":"Порядок проведения предварительного слушания","sub":[{"n":"1","text":"Предварительное слушание проводится в порядке, установленном настоящим Кодексом, с изъятиями, предусмотренными настоящей главой."},{"n":"2","text":"Стороны вправе заявить ходатайства, представить суду документы."}]},{"n":"Статья 150","title":"Решения, принимаемые на предварительном слушании","sub":[{"n":"1","text":"По результатам предварительного слушания судья принимает одно из следующих решений:"},{"n":"1)","text":"о направлении уголовного дела по подсудности;","lvl":1},{"n":"2)","text":"о возвращении уголовного дела прокурору;","lvl":1},{"n":"3)","text":"о приостановлении производства по уголовному делу;","lvl":1},{"n":"4)","text":"о прекращении уголовного дела;","lvl":1},{"n":"5)","text":"о назначении судебного заседания.","lvl":1}]},{"h":"Глава 14. Судебное разбирательство"},{"n":"Статья 151","title":"Непосредственность и устность","sub":[{"n":"1","text":"Судебное разбирательство происходит при непосредственном исследовании всех доказательств по делу."},{"n":"2","text":"Приговор суда может быть основан лишь на тех доказательствах, которые были исследованы в судебном заседании."}]},{"n":"Статья 152","title":"Гласность","sub":[{"n":"1","text":"Разбирательство дел во всех судах открытое, за исключением случаев, предусмотренных законом."},{"n":"2","text":"Закрытое судебное разбирательство допускается на основании определения или постановления суда в случаях, когда это может привести к разглашению государственной или иной охраняемой законом тайны."}]},{"n":"Статья 153","title":"Неизменность состава суда","sub":[{"n":"1","text":"Уголовное дело рассматривается одним и тем же судьей или одним и тем же составом суда."},{"n":"2","text":"Если кто-либо из судей лишен возможности продолжать участие в судебном заседании, то он заменяется другим судьей, и разбирательство уголовного дела начинается сначала."}]},{"n":"Статья 154","title":"Председательствующий","sub":[{"n":"1","text":"Председательствующий руководит судебным заседанием, принимает все предусмотренные настоящим Кодексом меры по обеспечению состязательности и равноправия сторон."}]},{"n":"Статья 155","title":"Равенство прав сторон","sub":[{"n":"1","text":"В судебном заседании стороны обвинения и защиты пользуются равными правами на заявление отводов и ходатайств, представление доказательств, участие в их исследовании, выступление в судебных прениях."}]},{"n":"Статья 156","title":"Участие обвинителя","sub":[{"n":"1","text":"Участие государственного обвинителя в судебном разбирательстве обязательно."},{"n":"2","text":"Государственный обвинитель представляет доказательства и участвует в их исследовании, излагает суду свое мнение по существу обвинения."}]},{"n":"Статья 157","title":"Участие подсудимого","sub":[{"n":"1","text":"Судебное разбирательство проводится с участием подсудимого, явка которого в суд обязательна."},{"n":"2","text":"Разбирательство уголовного дела в отсутствие подсудимого может быть допущено лишь в случаях, предусмотренных законом."}]},{"n":"Статья 158","title":"Участие защитника","sub":[{"n":"1","text":"Защитник участвует в судебном разбирательстве и пользуется правами, предусмотренными настоящим Кодексом."}]},{"n":"Статья 159","title":"Участие потерпевшего","sub":[{"n":"1","text":"Потерпевший участвует в судебном разбирательстве и пользуется правами, предусмотренными настоящим Кодексом."}]},{"n":"Статья 160","title":"Участие гражданского истца и гражданского ответчика","sub":[{"n":"1","text":"Гражданский истец, гражданский ответчик и их представители участвуют в судебном разбирательстве."}]},{"n":"Статья 161","title":"Участие специалиста","sub":[{"n":"1","text":"Специалист может быть вызван в судебное заседание для участия в исследовании доказательств."}]},{"n":"Статья 162","title":"Пределы судебного разбирательства","sub":[{"n":"1","text":"Разбирательство дела в суде производится только в отношении обвиняемых и лишь по тому обвинению, которое им предъявлено."},{"n":"2","text":"Изменение обвинения в судебном разбирательстве допускается, если этим не ухудшается положение подсудимого и не нарушается его право на защиту."}]},{"n":"Статья 163","title":"Отложение и приостановление судебного разбирательства","sub":[{"n":"1","text":"При невозможности рассмотрения дела в данном судебном заседании суд откладывает разбирательство."},{"n":"2","text":"Суд приостанавливает производство по делу в случаях, предусмотренных законом."}]},{"n":"Статья 164","title":"Прекращение уголовного дела в судебном заседании","sub":[{"n":"1","text":"Суд прекращает уголовное дело при наличии оснований, предусмотренных настоящим Кодексом."}]},{"n":"Статья 165","title":"Решение вопроса о мере пресечения","sub":[{"n":"1","text":"Во время судебного разбирательства суд вправе избрать, изменить или отменить меру пресечения в отношении подсудимого."}]},{"n":"Статья 166","title":"Порядок судебного разбирательства","sub":[{"n":"1","text":"Судебное разбирательство состоит из следующих частей: подготовительная часть, судебное следствие, прения сторон, последнее слово подсудимого, постановление приговора."}]},{"n":"Статья 167","title":"Судебное следствие","sub":[{"n":"1","text":"Судебное следствие начинается с оглашения государственным обвинителем предъявленного подсудимому обвинения."},{"n":"2","text":"Председательствующий опрашивает подсудимого, понятна ли ему суть обвинения и признает ли он себя виновным."},{"n":"3","text":"Очередность исследования доказательств определяется судом с учетом мнения сторон."}]},{"n":"Статья 168","title":"Прения сторон","sub":[{"n":"1","text":"Прения сторон состоят из речей обвинителя и защитника."},{"n":"2","text":"После произнесения речей участники прений могут выступить с репликами."}]},{"n":"Статья 169","title":"Последнее слово подсудимого","sub":[{"n":"1","text":"После окончания прений сторон подсудимому предоставляется последнее слово."},{"n":"2","text":"Никакие вопросы к подсудимому во время его последнего слова не допускаются."}]},{"n":"Статья 170","title":"Постановление приговора","sub":[{"n":"1","text":"Заслушав последнее слово подсудимого, суд немедленно удаляется в совещательную комнату для постановления приговора."},{"n":"2","text":"Приговор постановляется именем Российской Федерации."}]},{"h":"Глава 15. Приговор"},{"n":"Статья 171","title":"Законность, обоснованность и справедливость приговора","sub":[{"n":"1","text":"Приговор суда должен быть законным, обоснованным и справедливым."},{"n":"2","text":"Приговор признается таковым, если он постановлен в соответствии с требованиями настоящего Кодекса и основан на правильном применении уголовного закона."}]},{"n":"Статья 172","title":"Виды приговоров","sub":[{"n":"1","text":"Приговор может быть обвинительным или оправдательным."},{"n":"2","text":"Обвинительный приговор постановляется в случаях, если в ходе судебного разбирательства виновность подсудимого в совершении преступления доказана."},{"n":"3","text":"Оправдательный приговор постановляется, если не установлено событие преступления, подсудимый не причастен к совершению преступления, в деянии подсудимого нет состава преступления."}]},{"n":"Статья 173","title":"Порядок постановления приговора","sub":[{"n":"1","text":"Приговор постановляется в совещательной комнате."},{"n":"2","text":"При постановлении приговора суд разрешает следующие вопросы:"},{"n":"1)","text":"имело ли место деяние, в совершении которого обвиняется подсудимый;","lvl":1},{"n":"2)","text":"совершил ли это деяние подсудимый;","lvl":1},{"n":"3)","text":"является ли это деяние преступлением;","lvl":1},{"n":"4)","text":"виновен ли подсудимый в совершении этого преступления;","lvl":1},{"n":"5)","text":"подлежит ли подсудимый наказанию.","lvl":1},{"n":"3","text":"Приговор состоит из вводной, описательно-мотивировочной и резолютивной частей."},{"n":"4","text":"В вводной части приговора указываются: дата и место постановления; наименование суда; состав суда; данные о подсудимом; данные о государственном обвинителе, защитнике, потерпевшем; статья уголовного закона, по которой подсудимый предан суду."},{"n":"5","text":"В описательно-мотивировочной части приговора указываются: описание преступного деяния, признанного доказанным; доказательства, на которых основаны выводы суда; мотивы, по которым суд отверг другие доказательства; обстоятельства, смягчающие и отягчающие наказание; мотивы решения всех вопросов, относящихся к назначению наказания."},{"n":"6","text":"В резолютивной части приговора указываются: фамилия, имя и отчество подсудимого; решение о признании его виновным или невиновным; вид и размер наказания; решение о мере пресечения; решение о гражданском иске; решение о вещественных доказательствах."},{"n":"7","text":"Приговор подписывается всеми судьями, участвовавшими в его постановлении."},{"n":"8","text":"Исправления в приговоре должны быть оговорены и удостоверены подписями всех судей в совещательной комнате до его провозглашения."},{"n":"9","text":"Приговор провозглашается председательствующим в судебном заседании."},{"n":"10","text":"Все присутствующие в зале судебного заседания выслушивают приговор стоя."},{"n":"11","text":"Приговор может быть обжалован в апелляционном порядке в течение 10 суток со дня его провозглашения."}]},{"n":"Статья 174","title":"Оправдательный приговор","sub":[{"n":"1","text":"Оправдательный приговор постановляется при наличии оснований, предусмотренных статьей 172 настоящего Кодекса."},{"n":"2","text":"Оправданный подсудимый признается невиновным и подлежит немедленному освобождению в зале суда."}]},{"n":"Статья 175","title":"Обвинительный приговор","sub":[{"n":"1","text":"Обвинительный приговор постановляется при подтверждении виновности подсудимого."},{"n":"2","text":"Обвинительный приговор не может быть основан на предположениях."}]},{"n":"Статья 176","title":"Провозглашение приговора","sub":[{"n":"1","text":"Приговор провозглашается председательствующим."},{"n":"2","text":"Все присутствующие в зале судебного заседания выслушивают приговор стоя."}]},{"n":"Статья 177","title":"Вступление приговора в законную силу","sub":[{"n":"1","text":"Приговор вступает в законную силу по истечении срока на апелляционное обжалование, если он не был обжалован."}]},{"h":"Глава 16. Апелляционное производство"},{"n":"Статья 178","title":"Право апелляционного обжалования","sub":[{"n":"1","text":"Приговор суда первой инстанции может быть обжалован в апелляционном порядке сторонами."},{"n":"2","text":"Право апелляционного обжалования принадлежит осужденному, оправданному, их защитникам, государственному обвинителю, потерпевшему."}]},{"n":"Статья 179","title":"Сроки апелляционного обжалования","sub":[{"n":"1","text":"Апелляционная жалоба, представление могут быть поданы в течение 10 суток со дня постановления приговора."}]},{"n":"Статья 180","title":"Порядок принесения апелляционной жалобы","sub":[{"n":"1","text":"Апелляционная жалоба приносится через суд, постановивший приговор."}]},{"n":"Статья 181","title":"Действия суда первой инстанции после получения жалобы","sub":[{"n":"1","text":"Суд первой инстанции направляет апелляционную жалобу с уголовным делом в суд апелляционной инстанции."}]},{"n":"Статья 182","title":"Предмет апелляционного рассмотрения","sub":[{"n":"1","text":"Суд апелляционной инстанции проверяет законность, обоснованность и справедливость приговора."}]},{"n":"Статья 183","title":"Порядок рассмотрения дела в апелляции","sub":[{"n":"1","text":"Производство в суде апелляционной инстанции осуществляется по правилам производства в суде первой инстанции с изъятиями, установленными настоящей главой."}]},{"n":"Статья 184","title":"Решения, принимаемые судом апелляционной инстанции","sub":[{"n":"1","text":"Суд апелляционной инстанции принимает одно из следующих решений:"},{"n":"1)","text":"об оставлении приговора без изменения, а жалобы без удовлетворения;","lvl":1},{"n":"2)","text":"об отмене приговора и о вынесении нового приговора;","lvl":1},{"n":"3)","text":"об отмене приговора и о прекращении уголовного дела;","lvl":1},{"n":"4)","text":"об изменении приговора.","lvl":1},{"n":"2","text":"При рассмотрении уголовного дела в апелляционном порядке суд вправе: исследовать доказательства; допрашивать свидетелей, потерпевших, подсудимого; назначать судебную экспертизу; исследовать вещественные доказательства; оглашать протоколы следственных действий."},{"n":"3","text":"Суд апелляционной инстанции не вправе: ухудшать положение осужденного по жалобе потерпевшего или представлению прокурора, если это не связано с отменой приговора по основаниям, влекущим ухудшение положения осужденного; принимать решение о применении уголовного закона о более тяжком преступлении."},{"n":"4","text":"Приговор суда апелляционной инстанции может быть обжалован в кассационном порядке."},{"n":"5","text":"Апелляционное определение вступает в законную силу с момента его провозглашения."}]},{"n":"Статья 185","title":"Основания отмены или изменения приговора","sub":[{"n":"1","text":"Основаниями отмены или изменения приговора в апелляционном порядке являются:"},{"n":"1)","text":"несоответствие выводов суда фактическим обстоятельствам дела;","lvl":1},{"n":"2)","text":"существенное нарушение уголовно-процессуального закона;","lvl":1},{"n":"3)","text":"неправильное применение уголовного закона;","lvl":1},{"n":"4)","text":"несправедливость приговора.","lvl":1}]},{"h":"Глава 17. Исполнение приговора"},{"n":"Статья 186","title":"Вступление приговора в законную силу и обращение к исполнению","sub":[{"n":"1","text":"Приговор вступает в законную силу по истечении срока на апелляционное обжалование."},{"n":"2","text":"Приговор обращается к исполнению судом, постановившим его, не позднее 3 суток со дня вступления в законную силу."},{"n":"3","text":"Обращение приговора к исполнению производится путем направления копии приговора в орган, ведающий исполнением наказания."},{"n":"4","text":"В случае изменения приговора в апелляционном порядке к исполнению обращается приговор суда апелляционной инстанции."},{"n":"5","text":"Суд, постановивший приговор, обязан: вести учет обращенных к исполнению приговоров; контролировать своевременность исполнения; разрешать вопросы, связанные с исполнением приговора."},{"n":"6","text":"Вопросы, связанные с исполнением приговора, разрешаются судом в судебном заседании с участием: осужденного; защитника; прокурора; представителя органа, ведающего исполнением наказания."},{"n":"7","text":"По результатам рассмотрения вопроса, связанного с исполнением приговора, суд выносит постановление, которое может быть обжаловано в апелляционном порядке."}]},{"n":"Статья 187","title":"Вопросы, разрешаемые судом при исполнении приговора","sub":[{"n":"1","text":"Суд разрешает вопросы:"},{"n":"1)","text":"о возмещении вреда реабилитированному;","lvl":1},{"n":"2)","text":"о замене наказания в случае злостного уклонения от его отбывания;","lvl":1},{"n":"3)","text":"об условно-досрочном освобождении от отбывания наказания;","lvl":1},{"n":"4)","text":"о снятии судимости.","lvl":1}]},{"n":"Статья 188","title":"Порядок разрешения вопросов, связанных с исполнением приговора","sub":[{"n":"1","text":"Вопросы, связанные с исполнением приговора, разрешаются судом в судебном заседании в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 189","title":"Снятие судимости","sub":[{"n":"1","text":"Снятие судимости производится судом по месту жительства осужденного."}]},{"h":"Глава 18. Кассационное и надзорное производство"},{"n":"Статья 190","title":"Кассационное обжалование","sub":[{"n":"1","text":"Вступившие в законную силу приговор, определение, постановление суда могут быть обжалованы в кассационном порядке."}]},{"n":"Статья 191","title":"Порядок рассмотрения кассационных жалоб","sub":[{"n":"1","text":"Кассационные жалобы рассматриваются судом кассационной инстанции в судебном заседании в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 192","title":"Надзорное производство","sub":[{"n":"1","text":"Вступившие в законную силу приговор, определение, постановление суда могут быть пересмотрены в порядке надзора Президиумом Верховного Суда Российской Федерации."}]},{"n":"Статья 193","title":"Возобновление производства по уголовному делу ввиду новых или вновь открывшихся обстоятельств","sub":[{"n":"1","text":"Вступивший в законную силу приговор может быть отменен и производство по делу возобновлено ввиду новых или вновь открывшихся обстоятельств в порядке, установленном настоящим Кодексом."}]},{"h":"Часть 4. Особые производства"},{"h":"Глава 19. Производство по делам несовершеннолетних"},{"n":"Статья 194","title":"Обстоятельства, подлежащие установлению по делам несовершеннолетних","sub":[{"n":"1","text":"При производстве предварительного расследования и судебного разбирательства по уголовному делу о преступлении, совершенном несовершеннолетним, наряду с доказыванием обстоятельств, указанных в статье 33 настоящего Кодекса, устанавливаются:"},{"n":"1)","text":"возраст несовершеннолетнего, число, месяц и год рождения;","lvl":1},{"n":"2)","text":"условия жизни и воспитания несовершеннолетнего, уровень психического развития;","lvl":1},{"n":"3)","text":"влияние на несовершеннолетнего старших по возрасту лиц.","lvl":1}]},{"n":"Статья 195","title":"Задержание и меры пресечения для несовершеннолетних","sub":[{"n":"1","text":"Задержание несовершеннолетнего подозреваемого производится в порядке, установленном настоящим Кодексом."},{"n":"2","text":"О задержании, заключении под стражу или продлении срока содержания под стражей несовершеннолетнего незамедлительно уведомляются его родители или иные законные представители."}]},{"n":"Статья 196","title":"Допрос несовершеннолетнего","sub":[{"n":"1","text":"Допрос несовершеннолетнего подозреваемого, обвиняемого не может продолжаться без перерыва более 2 часов, а в общей сложности более 4 часов в день."},{"n":"2","text":"В допросе несовершеннолетнего подозреваемого, обвиняемого участвует защитник."}]},{"n":"Статья 197","title":"Участие законного представителя","sub":[{"n":"1","text":"Законный представитель несовершеннолетнего подозреваемого, обвиняемого допускается к участию в уголовном деле с момента первого допроса."}]},{"n":"Статья 198","title":"Участие педагога и психолога","sub":[{"n":"1","text":"В допросе несовершеннолетнего подозреваемого, обвиняемого, не достигшего возраста 16 лет, обязательно участие педагога или психолога."}]},{"n":"Статья 199","title":"Судебное разбирательство по делам несовершеннолетних","sub":[{"n":"1","text":"Судебное разбирательство по делам несовершеннолетних проводится в общем порядке с изъятиями, предусмотренными настоящей главой."}]},{"n":"Статья 200","title":"Освобождение несовершеннолетнего от уголовной ответственности","sub":[{"n":"1","text":"Несовершеннолетний, впервые совершивший преступление небольшой или средней тяжести, может быть освобожден от уголовной ответственности, если будет признано, что его исправление может быть достигнуто путем применения принудительных мер воспитательного воздействия."}]},{"h":"Глава 20. Производство о применении принудительных мер медицинского характера"},{"n":"Статья 201","title":"Основания применения принудительных мер медицинского характера","sub":[{"n":"1","text":"Принудительные меры медицинского характера применяются к лицам, совершившим общественно опасные деяния в состоянии невменяемости или у которых после совершения преступления наступило психическое расстройство."}]},{"n":"Статья 202","title":"Порядок производства","sub":[{"n":"1","text":"Производство о применении принудительных мер медицинского характера осуществляется в порядке, установленном настоящим Кодексом, с изъятиями, предусмотренными настоящей главой."}]},{"n":"Статья 203","title":"Судебное разбирательство","sub":[{"n":"1","text":"Судебное разбирательство по делам о применении принудительных мер медицинского характера проводится с участием прокурора и защитника."}]},{"n":"Статья 204","title":"Решения суда","sub":[{"n":"1","text":"Суд принимает одно из следующих решений:"},{"n":"1)","text":"об освобождении лица от уголовной ответственности и о применении к нему принудительных мер медицинского характера;","lvl":1},{"n":"2)","text":"о прекращении уголовного дела.","lvl":1}]},{"h":"Глава 21. Особый порядок судебного разбирательства"},{"n":"Статья 205","title":"Основания применения особого порядка","sub":[{"n":"1","text":"Особый порядок судебного разбирательства применяется при согласии обвиняемого с предъявленным ему обвинением."}]},{"n":"Статья 206","title":"Порядок заявления ходатайства","sub":[{"n":"1","text":"Обвиняемый вправе заявить ходатайство о постановлении приговора без проведения судебного разбирательства в связи с согласием с предъявленным обвинением."}]},{"n":"Статья 207","title":"Порядок судебного заседания","sub":[{"n":"1","text":"Судебное заседание проводится с участием подсудимого, его защитника и государственного обвинителя."}]},{"n":"Статья 208","title":"Пределы обжалования приговора","sub":[{"n":"1","text":"Приговор, постановленный в особом порядке, не может быть обжалован в апелляционном порядке по основанию несоответствия выводов суда фактическим обстоятельствам дела."}]},{"h":"Глава 22. Досудебное соглашение о сотрудничестве"},{"n":"Статья 209","title":"Порядок заключения досудебного соглашения","sub":[{"n":"1","text":"Досудебное соглашение о сотрудничестве заключается между прокурором и подозреваемым или обвиняемым."}]},{"n":"Статья 210","title":"Проведение предварительного следствия","sub":[{"n":"1","text":"Предварительное следствие по делу, выделенному в отдельное производство в связи с заключением досудебного соглашения, проводится в порядке, установленном настоящим Кодексом."}]},{"n":"Статья 211","title":"Судебное разбирательство","sub":[{"n":"1","text":"Судебное разбирательство проводится в порядке, установленном настоящим Кодексом, с изъятиями, предусмотренными настоящей главой."}]},{"n":"Статья 212","title":"Обжалование","sub":[{"n":"1","text":"Приговор, постановленный в отношении лица, с которым заключено досудебное соглашение, может быть обжалован в апелляционном порядке."}]},{"h":"Глава 23. Особенности производства по отдельным категориям лиц"},{"n":"Статья 213","title":"Категории лиц, в отношении которых применяется особый порядок","sub":[{"n":"1","text":"Особый порядок производства применяется в отношении:"},{"n":"1)","text":"члена Совета Федерации и депутата Государственной Думы;","lvl":1},{"n":"2)","text":"судьи Конституционного Суда, судьи федерального суда;","lvl":1},{"n":"3)","text":"прокурора;","lvl":1},{"n":"4)","text":"Председателя Счетной палаты;","lvl":1},{"n":"5)","text":"Уполномоченного по правам человека;","lvl":1},{"n":"6)","text":"Президента Российской Федерации, прекратившего исполнение своих полномочий.","lvl":1}]},{"n":"Статья 214","title":"Порядок возбуждения уголовного дела","sub":[{"n":"1","text":"Решение о возбуждении уголовного дела в отношении лица, указанного в статье 213 настоящего Кодекса, принимается в особом порядке, установленном настоящим Кодексом."}]},{"n":"Статья 215","title":"Особенности задержания и избрания меры пресечения","sub":[{"n":"1","text":"Задержание лица, указанного в статье 213 настоящего Кодекса, производится в особом порядке, установленном настоящим Кодексом."}]},{"n":"Статья 216","title":"Направление дела в суд","sub":[{"n":"1","text":"Уголовное дело в отношении лица, указанного в статье 213 настоящего Кодекса, направляется в суд в порядке, установленном настоящим Кодексом."}]},{"h":"Часть 5. Оперативно-розыскная деятельность"},{"h":"Глава 24. Полномочия и проведение оперативно-розыскных мероприятий"},{"n":"Статья 217","title":"Понятие и цели оперативно-розыскной деятельности","sub":[{"n":"1","text":"Оперативно-розыскная деятельность — вид деятельности, осуществляемый гласно и негласно оперативными подразделениями государственных органов в целях защиты жизни, здоровья, прав и свобод человека, а также для предупреждения, пресечения и раскрытия преступлений."}]},{"n":"Статья 218","title":"Субъекты, имеющие право на проведение оперативно-розыскной деятельности","sub":[{"n":"1","text":"Право на проведение оперативно-розыскных мероприятий предоставляется оперативным подразделениям МВД, ФСБ, ФСИН, ФССП и иных уполномоченных федеральных органов исполнительной власти."}]},{"n":"Статья 219","title":"Основания для проведения оперативно-розыскных мероприятий","sub":[{"n":"1","text":"Основаниями для проведения оперативно-розыскных мероприятий являются: наличие возбужденного уголовного дела; ставшие известными сведения о подготавливаемом, совершаемом или совершенном противоправном деянии; поручения следователя, руководителя следственного органа, дознавателя или определения суда."}]},{"n":"Статья 220","title":"Сокрытие личности и конфиденциальность при осуществлении оперативно-розыскной деятельности","sub":[{"n":"1","text":"В целях защиты оперативников и конфидентов допускается использование документов, шифрующих личность должностных лиц, ведомственную принадлежность предприятий, подразделений, организаций и транспортных средств."}]},{"n":"Статья 221","title":"Особенности проведения оперативно-розыскной деятельности по предупреждению и пресечению коррупции","sub":[{"n":"1","text":"Оперативно-розыскные мероприятия по выявлению и пресечению коррупционных преступлений проводятся с использованием специальных технических средств контроля, оперативных экспериментов и контрольных закупок в строгом соответствии с требованиями закона."}]},{"n":"Статья 222","title":"Заведение дел оперативного учета","sub":[{"n":"1","text":"При наличии оснований, предусмотренных статьей 219 настоящего Кодекса, оперативный орган заводит дело оперативного учета, в рамках которого систематизируются все полученные материалы."}]},{"n":"Статья 223","title":"Временные рамки и сроки проведения оперативно-розыскной деятельности","sub":[{"n":"1","text":"Сроки проведения отдельных оперативно-розыскных мероприятий и ведения дел оперативного учета устанавливаются нормативными актами ведомств и прекращаются при достижении целей либо установлении невозможности их решения."}]},{"n":"Статья 224","title":"Полномочия органов, осуществляющих оперативно-розыскную деятельность","sub":[{"n":"1","text":"Органы, осуществляющие оперативно-розыскную деятельность, имеют право производить оперативно-розыскные мероприятия, задействовать конфиденциальное сотрудничество граждан, использовать служебные помещения, транспортные средства и спецсредства."}]},{"n":"Статья 225","title":"Исследование предметов и документов","sub":[{"n":"1","text":"Исследование предметов и документов в рамках оперативно-розыскной деятельности заключается в их научном или техническом осмотре и оценке специалистом для получения сведений, имеющих значение для решения задач оперативно-розыскной деятельности."}]},{"n":"Статья 226","title":"Обследование помещений, зданий, сооружений, участков местности и транспортных средств","sub":[{"n":"1","text":"Обследование помещений, зданий, участков местности и транспортных средств заключается в их осмотре на предмет обнаружения следов преступления, разыскиваемых лиц или предметов, доступ к которым ограничен."},{"n":"2","text":"Обследование жилых помещений допускается только на основании судебного решения."}]},{"n":"Статья 227","title":"Контроль почтовых отправлений, прослушивание телефонных переговоров","sub":[{"n":"1","text":"Прослушивание телефонных переговоров и контроль сообщений допускаются только на основании судебного решения в отношении лиц, подозреваемых или обвиняемых в совершении преступлений средней тяжести, тяжких или особо тяжких преступлений."}]},{"n":"Статья 228","title":"Снятие информации с технических каналов связи","sub":[{"n":"1","text":"Снятие информации с технических каналов связи включает использование специального оборудования для перехвата данных и осуществляется по решению суда."}]},{"n":"Статья 229","title":"Контрольная закупка и контролируемая поставка","sub":[{"n":"1","text":"Контрольная закупка заключается в искусственном создании ситуации покупки товаров, предметов или веществ (в том числе изъятых из гражданского оборота) с целью фиксации противоправной деятельности."},{"n":"2","text":"Контролируемая поставка заключается в перемещении предметов или веществ под контролем оперативных органов."}]},{"n":"Статья 230","title":"Получение компьютерной информации и снятие записей с камер видеонаблюдения","sub":[{"n":"1","text":"Получение компьютерной информации и снятие записей с видеокамер осуществляется оперативным сотрудником путем изъятия, копирования или удаленного доступа к электронным носителям с составлением соответствующего акта."}]},{"n":"Статья 231","title":"Представление результатов оперативно-розыскной деятельности органу дознания, следователю или в суд","sub":[{"n":"1","text":"Результаты оперативно-розыскной деятельности могут быть использованы в доказывании по уголовным делам в соответствии с положениями настоящего Кодекса и передаются следователю или в суд на основании постановления руководителя органа, осуществляющего оперативно-розыскную деятельность."}]},{"n":"Статья 232","title":"Содействие граждан органам, осуществляющим оперативно-розыскную деятельность","sub":[{"n":"1","text":"Граждане Российской Федерации могут с их согласия привлекаться к подготовке или проведению оперативно-розыскных мероприятий с сохранением по их желанию конфиденциальности."}]},{"n":"Статья 233","title":"Финансовое и материально-техническое обеспечение оперативно-розыскной деятельности","sub":[{"n":"1","text":"Финансовое обеспечение оперативно-розыскной деятельности осуществляется за счет средств федерального бюджета."}]},{"n":"Статья 234","title":"Контроль за оперативно-розыскной деятельностью","sub":[{"n":"1","text":"Контроль за оперативно-розыскной деятельностью осуществляют Президент Российской Федерации, Федеральное Собрание, Правительство Российской Федерации в пределах полномочий, определяемых законодательством."}]},{"n":"Статья 235","title":"Ответственность за нарушение законодательства об оперативно-розыскной деятельности","sub":[{"n":"1","text":"Нарушение законодательства об оперативно-розыскной деятельности влечет ответственность в соответствии с законодательством Российской Федерации."}]}]};
